def example_activity(assay_chembl_id, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "example_activity"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _get_service_status_row(meta_rows):
        for r in meta_rows:
            if isinstance(r, dict) and r.get("kind") == "SERVICE_STATUS" and r.get("status") == "active":
                return r
        return None

    def _ensure_service_row(meta_rows):
        sr = _get_service_status_row(meta_rows)
        if sr is None:
            # Service is callable without explicit auth; create status row so logging/quota can function.
            sr = {
                "id": f"chs_meta_{int(time.time()*1000)}{random.randint(100,999)}",
                "kind": "SERVICE_STATUS",
                "service_status": "ok",
                "service_name": "ChEMBL Server",
                "message": "Auto-created service status row",
                "status": "active",
                "cache_payload": {},
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            meta_rows.append(sr)
        if not isinstance(sr.get("cache_payload"), dict):
            sr["cache_payload"] = {}
        cp = sr["cache_payload"]
        if not isinstance(cp.get("request_log"), list):
            cp["request_log"] = []
        if not isinstance(cp.get("quota"), dict):
            # Best-effort defaults (schema doesn't declare explicit quota fields)
            cp["quota"] = {"window_seconds": 60, "max_requests": 120}
        return sr

    def _check_rate_limit(service_row):
        cp = service_row.get("cache_payload") if isinstance(service_row.get("cache_payload"), dict) else {}
        quota = cp.get("quota") if isinstance(cp.get("quota"), dict) else {}
        window_seconds = quota.get("window_seconds", 60)
        max_requests = quota.get("max_requests", 120)
        if not isinstance(window_seconds, int) or window_seconds <= 0:
            window_seconds = 60
        if not isinstance(max_requests, int) or max_requests <= 0:
            max_requests = 120

        req_log = cp.get("request_log", [])
        if not isinstance(req_log, list):
            return None

        now = datetime.datetime.utcnow()
        start = now - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for rec in req_log:
            if not isinstance(rec, dict):
                continue
            ts = _parse_ts(rec.get("timestamp"))
            if ts is not None and ts >= start:
                cnt += 1
        if cnt >= max_requests:
            return _err("RATE_LIMIT", "Too many requests in the current time window.", window_seconds=window_seconds, max_requests=max_requests)
        return None

    def _append_req(meta_rows, service_row, status, error_code=None):
        cp = service_row["cache_payload"]
        req_log = cp["request_log"]
        rec = {
            "id": f"req_{int(time.time()*1000)}{random.randint(100,999)}",
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_used": None,
        }
        if error_code:
            rec["error_code"] = error_code
        req_log.append(rec)
        service_row["updated_at"] = _now_iso()
        _save("service_metadata.json", meta_rows)

    # Validate input
    if assay_chembl_id is None or not isinstance(assay_chembl_id, str):
        meta = _load("service_metadata.json")
        if not isinstance(meta, list):
            meta = []
        sr = _ensure_service_row(meta)
        rl = _check_rate_limit(sr)
        if rl:
            _append_req(meta, sr, "error", "RATE_LIMIT")
            return rl
        _append_req(meta, sr, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "assay_chembl_id is required and must be a string.", assay_chembl_id=assay_chembl_id)
    assay_chembl_id = assay_chembl_id.strip()
    if not assay_chembl_id:
        meta = _load("service_metadata.json")
        if not isinstance(meta, list):
            meta = []
        sr = _ensure_service_row(meta)
        rl = _check_rate_limit(sr)
        if rl:
            _append_req(meta, sr, "error", "RATE_LIMIT")
            return rl
        _append_req(meta, sr, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "assay_chembl_id must be a non-empty string.", assay_chembl_id=assay_chembl_id)

    # Quota/rate limit & request log (observable dynamics)
    meta = _load("service_metadata.json")
    if not isinstance(meta, list):
        meta = []
    sr = _ensure_service_row(meta)
    rl = _check_rate_limit(sr)
    if rl:
        _append_req(meta, sr, "error", "RATE_LIMIT")
        return rl

    # Resolve assay entity: MUST be entity_type=ASSAY; status can be active/deprecated/merged (mirror should still resolve).
    entities = _load("chembl_entities.json")
    if not isinstance(entities, list):
        entities = []

    assay_entity = None
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("chembl_id") == assay_chembl_id and e.get("entity_type") == "ASSAY":
            assay_entity = e
            break

    if assay_entity is None:
        _append_req(meta, sr, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Assay not found for assay_chembl_id.", assay_chembl_id=assay_chembl_id)

    assay_entity_id = assay_entity.get("id")

    acts = _load("activities.json")
    if not isinstance(acts, list):
        acts = []

    # Filter: assay_entity_id match AND status='active' only
    out = []
    for a in acts:
        if not isinstance(a, dict):
            continue
        if a.get("assay_entity_id") == assay_entity_id and a.get("status") == "active":
            out.append(a)

    _append_req(meta, sr, "ok", None)
    return {
        "assay_chembl_id": assay_chembl_id,
        "assay_entity_id": assay_entity_id,
        "count": len(out),
        "activities": out,
    }

def example_activity_supplementary_data_by_activity(activity_chembl_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "example_activity_supplementary_data_by_activity"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _get_service_status_row(meta_rows):
        if not isinstance(meta_rows, list):
            return None
        candidates = [r for r in meta_rows if isinstance(r, dict) and r.get("kind") == "SERVICE_STATUS"]
        for r in candidates:
            if r.get("status") == "active":
                return r
        return candidates[0] if candidates else None

    def _ensure_audit(meta_rows, service_row):
        now = _now_iso()
        if not isinstance(service_row, dict):
            return meta_rows
        payload = service_row.get("cache_payload")
        if not isinstance(payload, dict):
            payload = {}
            service_row["cache_payload"] = payload
        log = payload.get("request_log")
        if not isinstance(log, list):
            log = []
            payload["request_log"] = log
        usage = payload.get("usage")
        if not isinstance(usage, dict):
            usage = {}
            payload["usage"] = usage
        by_ep = usage.get("by_endpoint")
        if not isinstance(by_ep, dict):
            by_ep = {}
            usage["by_endpoint"] = by_ep
        if not isinstance(usage.get("total_calls"), int):
            usage["total_calls"] = 0
        usage["total_calls"] += 1
        by_ep[endpoint] = int(by_ep.get(endpoint, 0) or 0) + 1
        service_row["updated_at"] = now
        return meta_rows

    def _check_limits(meta_rows, service_row):
        if not isinstance(service_row, dict):
            return None
        payload = service_row.get("cache_payload")
        if not isinstance(payload, dict):
            return None
        log = payload.get("request_log")
        if not isinstance(log, list):
            return None
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=60)
        day_cutoff = now - datetime.timedelta(days=1)
        in_window = 0
        in_day = 0
        for r in log:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("ts") or r.get("timestamp"))
            if ts is None:
                continue
            if ts >= day_cutoff:
                in_day += 1
            if ts >= cutoff:
                in_window += 1
        if in_window >= 120:
            return _err("RATE_LIMIT", "Too many requests.")
        if in_day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    def _append_log(meta_rows, service_row, status, detail=None):
        if not isinstance(service_row, dict):
            return
        now = _now_iso()
        latency_ms = int((time.time() - t0) * 1000)
        payload = service_row.get("cache_payload")
        if not isinstance(payload, dict):
            payload = {}
            service_row["cache_payload"] = payload
        log = payload.get("request_log")
        if not isinstance(log, list):
            log = []
            payload["request_log"] = log
        rec = {"ts": now, "endpoint": endpoint, "status": status, "latency_ms": latency_ms}
        if detail is not None:
            rec["detail"] = detail
        log.append(rec)
        service_row["updated_at"] = now
        _save("service_metadata.json", meta_rows)

    if activity_chembl_id is None or not isinstance(activity_chembl_id, str):
        meta = _load("service_metadata.json")
        service_row = _get_service_status_row(meta)
        if isinstance(service_row, dict):
            meta = _ensure_audit(meta, service_row)
            _append_log(meta, service_row, "VALIDATION_ERROR", detail="activity_chembl_id must be a string")
        return _err("VALIDATION_ERROR", "activity_chembl_id must be a string.", activity_chembl_id=activity_chembl_id)

    meta = _load("service_metadata.json")
    service_row = _get_service_status_row(meta)
    if isinstance(service_row, dict):
        if service_row.get("status") != "active" or service_row.get("service_status") == "down":
            meta = _ensure_audit(meta, service_row)
            _append_log(meta, service_row, "UNAUTHORIZED", detail="service unavailable")
            return _err("UNAUTHORIZED", "Service is not available.")
        limit_err = _check_limits(meta, service_row)
        meta = _ensure_audit(meta, service_row)
        if limit_err:
            _append_log(meta, service_row, limit_err["error"]["code"], detail=limit_err["error"]["message"])
            return limit_err
        _append_log(meta, service_row, "STARTED")

    # Resolve: accept either ACTIVITY chembl_id OR internal entity id OR activities.activity_entity_id directly.
    entities = _load("chembl_entities.json")
    resolved_activity_entity_id = None
    if isinstance(entities, list):
        for e in entities:
            if not isinstance(e, dict):
                continue
            if e.get("entity_type") != "ACTIVITY":
                continue
            if e.get("chembl_id") == activity_chembl_id or e.get("id") == activity_chembl_id:
                resolved_activity_entity_id = e.get("id")
                break

    acts = _load("activities.json")
    if not isinstance(acts, list):
        acts = []

    activity_row = None
    if resolved_activity_entity_id is not None:
        for a in acts:
            if isinstance(a, dict) and a.get("activity_entity_id") == resolved_activity_entity_id:
                activity_row = a
                break
    else:
        # maybe caller passed activities.activity_entity_id directly
        for a in acts:
            if isinstance(a, dict) and a.get("activity_entity_id") == activity_chembl_id:
                activity_row = a
                resolved_activity_entity_id = a.get("activity_entity_id")
                break

    if activity_row is None:
        if isinstance(service_row, dict):
            _append_log(meta, service_row, "NOT_FOUND", detail={"activity_chembl_id": activity_chembl_id})
        return _err("NOT_FOUND", "Activity not found for activity_chembl_id.", activity_chembl_id=activity_chembl_id)

    supp = activity_row.get("supplementary_data")
    if not isinstance(supp, list):
        supp = []

    resp = {
        "activity_chembl_id": activity_chembl_id,
        "activity_entity_id": resolved_activity_entity_id,
        "count": len(supp),
        "supplementary_data": supp,
    }
    if isinstance(service_row, dict):
        _append_log(meta, service_row, "OK", detail={"count": len(supp)})
    return resp

