            _append_log(meta, service_row, limit_err["error"]["code"], detail=limit_err["error"]["message"])
            return limit_err
        _append_log(meta, service_row, "STARTED")

    catalog = _load("bio_catalog.json")
    if not isinstance(catalog, list):
        catalog = []

    # Equality filter on type_value, return active only (business rule).
    # If caller passes an internal entity id (audit defect), accept it as a type_value too (still equality).
    out = []
    for r in catalog:
        if not isinstance(r, dict):
            continue
        if r.get("catalog_type") != "ASSAY":
            continue
        if r.get("status") != "active":
            continue
        if r.get("type_value") == assay_type:
            out.append(r)

    # Reads with no matches return empty set (not error)
    resp = {"assay_type": assay_type, "count": len(out), "assays": out}
    if isinstance(service_row, dict):
        _append_log(meta, service_row, "OK", detail={"count": len(out)})
    return resp

