def example_atc_class(level1, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "example_atc_class",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": code,
            "error_message": message,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        # Best-effort rate limiting based on request_logs.json if present.
        logs = _load("request_logs.json")
        window_s = 60
        max_per_window = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)

        def _parse_ts(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        recent = 0
        for r in reversed(logs):
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts < cutoff:
                break
            recent += 1
            if recent > max_per_window:
                return False
        return True

    # Validate input
    if level1 is None or not isinstance(level1, str) or level1.strip() == "":
        if _enforce_limits() is False:
            _log("error", "RATE_LIMIT", "Too many requests")
            return _err("RATE_LIMIT", "Too many requests")
        _log("error", "VALIDATION_ERROR", "level1 is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "level1 is required and must be a non-empty string", field="level1")

    if _enforce_limits() is False:
        _log("error", "RATE_LIMIT", "Too many requests")
        return _err("RATE_LIMIT", "Too many requests")

    # Authorization is ambient; no explicit credential exists for this tool.
    # If the mirror has no data at all, treat as unauthorized only if nothing in store can serve.
    catalog = _load("bio_catalog.json")
    if not isinstance(catalog, list):
        _log("error", "UNAUTHORIZED", "Access not permitted")
        return _err("UNAUTHORIZED", "Access not permitted")

    # Filter
    matches = [
        r for r in catalog
        if isinstance(r, dict)
        and r.get("catalog_type") == "ATC_CLASS"
        and r.get("level1") == level1
        and r.get("status") == "active"
    ]

    if len(matches) == 0:
        # Vendor description says NOT_FOUND when no matches.
        _log("error", "NOT_FOUND", "No ATC classification records found for level1", meta={"level1": level1})
        return _err("NOT_FOUND", "No ATC classification records found for level1", level1=level1)

    resp = {"results": matches, "count": len(matches)}
    _log("ok", meta={"level1": level1, "count": len(matches)})
    return resp

