            usage["total_calls"] = 0
        usage["total_calls"] += 1
        by_ep[endpoint] = int(by_ep.get(endpoint, 0) or 0) + 1
        service_row["updated_at"] = now
        return meta_rows

    def _check_limits(service_row):
        if not isinstance(service_row, dict):
            return None
        payload = service_row.get("cache_payload")
        if not isinstance(payload, dict):
            return None
        log = payload.get("request_log")
        if not isinstance(log, list):
            return None
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=60)
        day_cutoff = now - datetime.timedelta(days=1)
        in_window = 0
        in_day = 0
        for r in log:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("ts") or r.get("timestamp"))
            if ts is None:
                continue
            if ts >= day_cutoff:
                in_day += 1
            if ts >= cutoff:
                in_window += 1
        if in_window >= 120:
            return _err("RATE_LIMIT", "Too many requests.")
        if in_day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    def _append_log(meta_rows, service_row, status, detail=None):
        if not isinstance(service_row, dict):
            return
        now = _now_iso()
        latency_ms = int((time.time() - t0) * 1000)
        payload = service_row.get("cache_payload")
        if not isinstance(payload, dict):
            payload = {}
            service_row["cache_payload"] = payload
        log = payload.get("request_log")
        if not isinstance(log, list):
            log = []
            payload["request_log"] = log
        rec = {"ts": now, "endpoint": endpoint, "status": status, "latency_ms": latency_ms}
        if detail is not None:
            rec["detail"] = detail
        log.append(rec)
        service_row["updated_at"] = now
        _save("service_metadata.json", meta_rows)

    if available_type is None or not isinstance(available_type, str) or not available_type.strip():
        return _err("VALIDATION_ERROR", "available_type must be a non-empty string", available_type=available_type)
    if q is None or not isinstance(q, str) or not q.strip():
        return _err("VALIDATION_ERROR", "q must be a non-empty string", q=q)

    meta = _load("service_metadata.json")
    service_row = _get_service_status_row(meta)
    if isinstance(service_row, dict):
        if service_row.get("status") != "active" or service_row.get("service_status") == "down":
            meta = _ensure_audit(meta, service_row)
            _append_log(meta, service_row, "UNAUTHORIZED", detail="service unavailable")
            return _err("UNAUTHORIZED", "Service is not available.")
        limit_err = _check_limits(service_row)
        meta = _ensure_audit(meta, service_row)
        if limit_err:
            _append_log(meta, service_row, limit_err["error"]["code"], detail=limit_err["error"]["message"])
            return limit_err
        _append_log(meta, service_row, "STARTED")

    # Business rule: available_type maps to entity_type. Be permissive:
    # - accept an entity_type enum directly
    # - accept known endpoint-ish aliases
    # - if an internal chembl_entities.id is provided, treat it as "any type" (do not hard-reject)
    at = available_type.strip()
    at_u = at.upper()

    known_entity_types = {
        "MOLECULE", "MOLECULE_FORM", "COMPOUND_RECORD", "DRUG", "TARGET", "TARGET_COMPONENT",
        "ASSAY", "ACTIVITY", "DOCUMENT", "BIOTHERAPEUTIC", "BINDING_SITE", "CELL_LINE", "TISSUE",
        "ORGANISM", "ATC_CLASS", "PROTEIN_CLASS", "ASSAY_CLASS", "XREF_SOURCE", "SOURCE", "GO_SLIM",
        "DRUG_INDICATION", "DRUG_WARNING", "MECHANISM", "STRUCTURAL_ALERT", "DESCRIPTION"
    }
    alias = {
        "MOLECULES": "MOLECULE",
        "MOLECULE_FORMS": "MOLECULE_FORM",
        "COMPOUND_RECORDS": "COMPOUND_RECORD",
        "DRUGS": "DRUG",
        "TARGETS": "TARGET",
        "TARGET_COMPONENTS": "TARGET_COMPONENT",
        "ASSAYS": "ASSAY",
        "ACTIVITIES": "ACTIVITY",
        "DOCUMENTS": "DOCUMENT",
        "BIOTHERAPEUTICS": "BIOTHERAPEUTIC",
        "BINDING_SITES": "BINDING_SITE",
        "CELL_LINES": "CELL_LINE",
        "TISSUES": "TISSUE",
        "ORGANISMS": "ORGANISM",
        "ATC": "ATC_CLASS",
        "ATC_CLASSES": "ATC_CLASS",
        "PROTEIN_CLASSIFICATION": "PROTEIN_CLASS",
        "PROTEIN_CLASSES": "PROTEIN_CLASS",
        "ASSAY_CLASSES": "ASSAY_CLASS",
        "XREF": "XREF_SOURCE",
        "XREF_SOURCES": "XREF_SOURCE",
        "SOURCES": "SOURCE",
        "GO": "GO_SLIM",
        "GO_SLIMS": "GO_SLIM",
        "DRUG_INDICATIONS": "DRUG_INDICATION",
        "DRUG_WARNINGS": "DRUG_WARNING",
        "MECHANISMS": "MECHANISM",
        "STRUCTURAL_ALERTS": "STRUCTURAL_ALERT",
        "DESCRIPTIONS": "DESCRIPTION",
    }

    resolved_entity_type = None
    if at_u in known_entity_types:
        resolved_entity_type = at_u
    elif at_u in alias:
        resolved_entity_type = alias[at_u]
    else:
        # If it's a known internal id (audit defect), do not reject; search across all types.
        entities = _load("chembl_entities.json")
        if isinstance(entities, list) and any(isinstance(e, dict) and e.get("id") == at for e in entities):
            resolved_entity_type = None  # all types
        else:
            # Also accept catalog_type values as a mapping (same enum set mostly)
            if at_u in {
                "ASSAY_CLASS", "ATC_CLASS", "BINDING_SITE", "BIOTHERAPEUTIC", "CELL_LINE", "COMPOUND_RECORD",
                "DRUG", "DRUG_INDICATION", "DRUG_WARNING", "GO_SLIM", "MECHANISM", "MOLECULE", "MOLECULE_FORM",
                "ORGANISM", "PROTEIN_CLASS", "SOURCE", "TARGET", "TARGET_COMPONENT", "TISSUE", "XREF_SOURCE",
                "STRUCTURAL_ALERT", "DESCRIPTION", "DOCUMENT"
            }:
                resolved_entity_type = at_u
            else:
                if isinstance(service_row, dict):
                    _append_log(meta, service_row, "VALIDATION_ERROR", detail={"available_type": available_type})
                return _err(
                    "VALIDATION_ERROR",
                    "available_type is not a supported lookup category",
                    available_type=available_type
                )

    q_raw = q.strip()
    q_l = q_raw.lower()

    entities = _load("chembl_entities.json")
    if not isinstance(entities, list):
        entities = []

    matches = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("status") not in ("active", "deprecated", "merged"):
            continue
        if resolved_entity_type is not None and e.get("entity_type") != resolved_entity_type:
            continue

        chembl_id = e.get("chembl_id")
        off = e.get("official_name")
        desc = e.get("description_text")

        ok = False
        if isinstance(chembl_id, str) and chembl_id.lower().startswith(q_l):
            ok = True
        if not ok and isinstance(off, str) and q_l in off.lower():
            ok = True
        if not ok and isinstance(desc, str) and q_l in desc.lower():
            ok = True
        if ok:
            matches.append({"chembl_id": chembl_id, "entity_type": e.get("entity_type"), "id": e.get("id")})

    # Unpaginated list, empty set is allowed (read tools do not error)
    resp = {
        "available_type": available_type,
        "resolved_entity_type": resolved_entity_type,
        "q": q_raw,
        "count": len(matches),
        "results": matches,
    }
    if isinstance(service_row, dict):
        _append_log(meta, service_row, "OK", detail={"count": len(matches)})
    return resp

def example_chembl_release(**_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    _t0 = time.time()

    caller = "ambient"
    endpoint = "example_chembl_release"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    # rate limit
    now = datetime.datetime.utcnow()
    window_s = 60
    limit_per_min = 120
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("caller") != caller:
            continue
        ts = _parse_dt(r.get("timestamp"))
        if ts and ts >= cutoff:
            recent += 1
    if recent >= limit_per_min:
        latency_ms = int((time.time() - _t0) * 1000)
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
                "timestamp": _now_iso(),
                "endpoint": endpoint,
                "caller": caller,
                "status": "RATE_LIMIT",
                "latency_ms": latency_ms,
            }
        )
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Too many requests")

    meta = _load("service_metadata.json")
    if not isinstance(meta, list):
        meta = []

    releases = []
    for r in meta:
        if not isinstance(r, dict):
            continue
        if r.get("kind") != "CHEMBL_RELEASE":
            continue
        if r.get("status") not in ("active", "expired"):
            continue
        # constraints say chembl_version and release_date not null for CHEMBL_RELEASE
        if not isinstance(r.get("chembl_version"), str) or not r.get("chembl_version"):
            continue
        if not isinstance(r.get("release_date"), str) or not r.get("release_date"):
            continue
        releases.append(r)

    releases.sort(key=lambda x: (_parse_dt(x.get("release_date")) or datetime.datetime.min), reverse=True)

    latency_ms = int((time.time() - _t0) * 1000)
    logs.append(
        {
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "caller": caller,
            "status": "OK",
            "latency_ms": latency_ms,
        }
    )
    _save("request_logs.json", logs)

    # Unpaginated list
    return {"results": releases, "count": len(releases)}

