        if isinstance(nv, str) and nv.strip().casefold() == q:
            out = dict(r)
            ent = ent_by_id.get(r.get("entity_id"))
            if isinstance(ent, dict) and ent.get("chembl_id"):
                out["chembl_id"] = ent.get("chembl_id")
