def example_drug(drug_type, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, endpoint, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        payload = _load("service_metadata.json")
        row = None
        for r in payload:
            if isinstance(r, dict) and r.get("kind") == "SERVICE_STATUS":
                row = r
                break
        if row is None:
            rid = "01" + "".join(random.choice("0123456789ABCDEFGHJKMNPQRSTVWXYZ") for _ in range(24))
            row = {
                "id": rid,
                "kind": "SERVICE_STATUS",
                "chembl_version": None,
                "release_date": None,
                "service_name": "ChEMBL Server",
                "service_status": "ok",
                "message": "",
                "cache_key": None,
                "cache_payload": {"request_log": [], "usage": {"total_calls": 0, "by_endpoint": {}}},
                "expires_at": None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            payload.append(row)

        cp = row.get("cache_payload")
        if not isinstance(cp, dict):
            cp = {}
            row["cache_payload"] = cp

        log = cp.get("request_log")
        if not isinstance(log, list):
            log = []
            cp["request_log"] = log

        usage = cp.get("usage")
        if not isinstance(usage, dict):
            usage = {}
            cp["usage"] = usage

        usage["total_calls"] = int(usage.get("total_calls", 0) or 0) + 1
        by_ep = usage.get("by_endpoint")
        if not isinstance(by_ep, dict):
            by_ep = {}
        by_ep[endpoint] = int(by_ep.get(endpoint, 0) or 0) + 1
        usage["by_endpoint"] = by_ep

        window_s = 60
        rate_limit = 120
        daily_quota = 20000

        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        cutoff_iso = cutoff.replace(microsecond=0).isoformat() + "Z"
        day_cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=1)
        day_cutoff_iso = day_cutoff.replace(microsecond=0).isoformat() + "Z"

        recent = 0
        last_day = 0
        for e in log:
            if not isinstance(e, dict):
                continue
            ts = e.get("ts")
            if isinstance(ts, str):
                if ts >= cutoff_iso:
                    recent += 1
                if ts >= day_cutoff_iso:
                    last_day += 1

        if recent >= rate_limit:
            log.append({"ts": now, "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": latency_ms, "detail": detail})
            row["updated_at"] = now
            _save("service_metadata.json", payload)
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_s, limit=rate_limit)

        if last_day >= daily_quota:
            log.append({"ts": now, "endpoint": endpoint, "status": "QUOTA_EXCEEDED", "latency_ms": latency_ms, "detail": detail})
            row["updated_at"] = now
            _save("service_metadata.json", payload)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", window_seconds=86400, limit=daily_quota)

        log.append({"ts": now, "endpoint": endpoint, "status": status, "latency_ms": latency_ms, "detail": detail})
        row["updated_at"] = now
        _save("service_metadata.json", payload)
        return None

    if not isinstance(drug_type, str) or not drug_type.strip():
        out = _err("VALIDATION_ERROR", "drug_type is required and must be a non-empty string")
        _log("VALIDATION_ERROR", "example_drug", detail={"drug_type": drug_type})
        return out
    drug_type = drug_type.strip()

    meta = _load("service_metadata.json")
    permitted = False
    for r in meta:
        if isinstance(r, dict) and r.get("kind") == "SERVICE_STATUS" and r.get("status") == "active" and r.get("service_status") in ("ok", "degraded"):
            permitted = True
            break
    if not permitted:
        out = _err("UNAUTHORIZED", "Not permitted to read drug data")
        _log("UNAUTHORIZED", "example_drug", detail={"drug_type": drug_type})
        return out

    rows = _load("bio_catalog.json")
    matches = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        if r.get("catalog_type") != "DRUG":
            continue
        if r.get("type_value") == drug_type:
            matches.append(r)

    if not matches:
        out = _err("NOT_FOUND", "Unknown drug_type or no matching drugs", drug_type=drug_type)
        _log("NOT_FOUND", "example_drug", detail={"drug_type": drug_type})
        return out

    _log("OK", "example_drug", detail={"count": len(matches), "drug_type": drug_type})
    return {"results": matches, "count": len(matches)}

