    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "ok"

    if molecule_type is None or not isinstance(molecule_type, str) or not molecule_type.strip():
        status = "validation_error"
        return _err("VALIDATION_ERROR", "molecule_type is required and must be a non-empty string.")

    mt = molecule_type.strip()

    # Equality filtering for type-based endpoints:
    # "example_assay(assay_type) returns bio_catalog rows where catalog_type='ASSAY' and type_value equals assay_type"
    # Hence: catalog_type='MOLECULE' and type_value equals molecule_type, status='active'
    catalog = _load("bio_catalog.json")
