        if not isinstance(r, dict):
            continue
        if r.get("catalog_type") != "MOLECULE":
            continue
        if r.get("status") != "active":
            continue
        if r.get("type_value") == mt:
            e = ent_by_id.get(r.get("entity_id"))
            out = dict(r)
            if isinstance(e, dict):
                if e.get("chembl_id"):
                    out["chembl_id"] = e.get("chembl_id")
                if e.get("official_name") is not None:
                    out["official_name"] = e.get("official_name")
                if e.get("description_text") is not None:
                    out["description_text"] = e.get("description_text")
                out["entity_status"] = e.get("status")
                out["entity_type"] = e.get("entity_type")
            rows.append(out)

    if not rows:
        status = "not_found"
        return _err("NOT_FOUND", "Unknown molecule_type or no matching molecules.", molecule_type=molecule_type)

    return {
        "results": rows,
        "count": len(rows),
