            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log_call(status, latency_ms, error_code=None):
        # Best-effort logging to common vendor-like files if present; do not create new schema.
        ts = _now_iso()
        for fname in ("request_log.json", "requests.json", "usage.json", "audit_log.json"):
            path = os.path.join(_DB, fname)
