        if r.get("catalog_type") != "TARGET":
            continue
        if r.get("type_value") != target_type_norm:
            continue
        eid = r.get("entity_id")
        ent = ent_by_id.get(eid)
        if not ent:
            continue
        out = dict(r)
        out["chembl_id"] = ent.get("chembl_id")
        out["entity_type"] = ent.get("entity_type")
        out["official_name"] = ent.get("official_name")
        out["description_text"] = ent.get("description_text")
        matches.append(out)

    latency = int((time.time() - t0) * 1000)
    if not matches:
        _log_call("error", latency, "NOT_FOUND")
        return _err("NOT_FOUND", "No targets found for the supplied target_type", target_type=target_type_norm)

    _log_call("ok", latency)
    return {"results": matches, "count": len(matches)}

