                    "endpoint": "example_target_relation",
                    "status": status,
                    "latency_ms": latency_ms,
                    "timestamp": ts,
                }
                if error_code:
                    rec["error_code"] = error_code
                rows.append(rec)
                _save(fname, rows)
                break

    t0 = time.time()
    if not isinstance(relationship_type, str) or not relationship_type.strip():
        latency = int((time.time() - t0) * 1000)
        _log_call("error", latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "relationship_type is required and must be a non-blank string")

    relationship_type_norm = relationship_type.strip()

    bio = _ensure_list(_load("bio_catalog.json"))
    entities = _ensure_list(_load("chembl_entities.json"))
    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict) and e.get("id")}

    matches = []
    for r in bio:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        if r.get("catalog_type") != "TARGET_RELATION":
            continue
        if r.get("type_value") != relationship_type_norm:
            continue
        eid = r.get("entity_id")
        ent = ent_by_id.get(eid)
        if not ent:
            continue
        out = dict(r)
        out["chembl_id"] = ent.get("chembl_id")
        out["entity_type"] = ent.get("entity_type")
        out["official_name"] = ent.get("official_name")
        out["description_text"] = ent.get("description_text")
        matches.append(out)

