    if not matches:
        _log_call("error", latency, "NOT_FOUND")
        return _err("NOT_FOUND", "No target relationships found for the supplied relationship_type", relationship_type=relationship_type_norm)

    _log_call("ok", latency)
    return {"results": matches, "count": len(matches)}

