def example_xref_source(xref_name, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "example_xref_source"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _get_service_status_row(meta_rows):
        for r in meta_rows:
            if isinstance(r, dict) and r.get("kind") == "SERVICE_STATUS" and r.get("status") == "active":
                return r
        return None

    def _ensure_service_row(meta_rows):
        sr = _get_service_status_row(meta_rows)
        if sr is None:
            sr = {
                "id": f"chs_meta_{int(time.time()*1000)}{random.randint(100,999)}",
                "kind": "SERVICE_STATUS",
                "service_status": "ok",
                "service_name": "ChEMBL Server",
                "message": "Auto-created service status row",
                "status": "active",
                "cache_payload": {},
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            meta_rows.append(sr)
        if not isinstance(sr.get("cache_payload"), dict):
            sr["cache_payload"] = {}
        cp = sr["cache_payload"]
        if not isinstance(cp.get("request_log"), list):
            cp["request_log"] = []
        if not isinstance(cp.get("quota"), dict):
            cp["quota"] = {"window_seconds": 60, "max_requests": 120}
        return sr

    def _check_rate_limit(service_row):
        cp = service_row.get("cache_payload") if isinstance(service_row.get("cache_payload"), dict) else {}
        quota = cp.get("quota") if isinstance(cp.get("quota"), dict) else {}
        window_seconds = quota.get("window_seconds", 60)
        max_requests = quota.get("max_requests", 120)
        if not isinstance(window_seconds, int) or window_seconds <= 0:
            window_seconds = 60
        if not isinstance(max_requests, int) or max_requests <= 0:
            max_requests = 120

        req_log = cp.get("request_log", [])
        if not isinstance(req_log, list):
            return None

        now = datetime.datetime.utcnow()
        start = now - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for rec in req_log:
            if not isinstance(rec, dict):
                continue
            ts = _parse_ts(rec.get("timestamp"))
            if ts is not None and ts >= start:
                cnt += 1
        if cnt >= max_requests:
            return _err("RATE_LIMIT", "Too many requests in the current time window.", window_seconds=window_seconds, max_requests=max_requests)
        return None

    def _append_req(meta_rows, service_row, status, error_code=None):
        cp = service_row["cache_payload"]
        req_log = cp["request_log"]
        rec = {
            "id": f"req_{int(time.time()*1000)}{random.randint(100,999)}",
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_used": None,
        }
        if error_code:
            rec["error_code"] = error_code
        req_log.append(rec)
        service_row["updated_at"] = _now_iso()
        _save("service_metadata.json", meta_rows)

    # Validate
    if xref_name is None or not isinstance(xref_name, str):
        meta = _load("service_metadata.json")
        if not isinstance(meta, list):
            meta = []
        sr = _ensure_service_row(meta)
        rl = _check_rate_limit(sr)
        if rl:
            _append_req(meta, sr, "error", "RATE_LIMIT")
            return rl
        _append_req(meta, sr, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "xref_name is required and must be a string.", xref_name=xref_name)
    xref_name = xref_name.strip()
    if not xref_name:
        meta = _load("service_metadata.json")
        if not isinstance(meta, list):
            meta = []
        sr = _ensure_service_row(meta)
        rl = _check_rate_limit(sr)
        if rl:
            _append_req(meta, sr, "error", "RATE_LIMIT")
            return rl
        _append_req(meta, sr, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "xref_name must be non-empty.", xref_name=xref_name)

    meta = _load("service_metadata.json")
    if not isinstance(meta, list):
        meta = []
    sr = _ensure_service_row(meta)
    rl = _check_rate_limit(sr)
    if rl:
        _append_req(meta, sr, "error", "RATE_LIMIT")
        return rl

    catalog = _load("bio_catalog.json")
    if not isinstance(catalog, list):
        catalog = []

    # Business rule: name-based endpoints filter bio_catalog.name_value case-insensitive match; only status='active'
    q = xref_name.casefold()
    matches = []
    for r in catalog:
        if not isinstance(r, dict):
            continue
        if r.get("catalog_type") != "XREF_SOURCE":
            continue
        if r.get("status") != "active":
            continue
        nv = r.get("name_value")
        if isinstance(nv, str) and nv.casefold() == q:
            matches.append(r)

    if not matches:
        # vendor behavior for this tool: NOT_FOUND rather than empty set
        _append_req(meta, sr, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "No cross-reference source matches the supplied name.", xref_name=xref_name)

    _append_req(meta, sr, "ok", None)
    return {"count": len(matches), "results": matches}

def example_canonicalizeSmiles(smiles, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _find_log_collection():
        for fn in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _append_log(endpoint, status, credential_used=None, error_code=None):
        fn = _find_log_collection()
        if not fn:
            return
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + str(int(time.time() * 1000)),
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_used": credential_used,
            "error_code": error_code
        })
        _save(fn, logs)

    # ---- Validation ----
    if not isinstance(smiles, str):
        _append_log("example_canonicalizeSmiles", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "smiles must be a string")
    raw = smiles.strip()
    if not raw:
        _append_log("example_canonicalizeSmiles", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "smiles is required")

    # ---- Helper: simplistic offline "canonicalization" ----
    # Note: True SMILES canonicalization requires chemistry toolkits. Offline server uses a stable normalization
    # that supports caching and deterministic keys, and flags obviously invalid inputs.
    def _canonicalize(s):
        # Reject clearly invalid strings (whitespace inside, control chars, too long)
        if any(ord(c) < 32 for c in s):
            return None
        if len(s) > 20000:
            return None
        # Minimal bracket balance check
        bal = 0
        for c in s:
            if c == "[":
                bal += 1
            elif c == "]":
                bal -= 1
                if bal < 0:
                    return None
        if bal != 0:
            return None
        # Normalize: strip, collapse internal whitespace, uppercase aromatic 'se','as'? avoid chemistry; keep as-is
        s2 = re.sub(r"\s+", "", s)
        if not s2:
            return None
        # Create deterministic canonical surrogate:
        # - keep original token order but normalize common separators; this is not chemical canonicalization
        # - for cache key stability across trivial formatting differences, use hash-prefixed normalized string
        digest = hashlib.sha256(s2.encode("utf-8")).hexdigest()
        return f"CANON:{digest}:{s2}"

    # ---- Cache lookup (service_metadata kind=SMILES_CACHE keyed by canonical_smiles) ----
    md = _load("service_metadata.json")
    if not isinstance(md, list):
        _append_log("example_canonicalizeSmiles", "error", error_code="INTERNAL_ERROR")
        return _err("INTERNAL_ERROR", "service_metadata store is corrupted")

    canonical = _canonicalize(raw)
    if canonical is None:
        _append_log("example_canonicalizeSmiles", "error", error_code="INVALID_SMILES")
        return _err("INVALID_SMILES", "Input cannot be parsed/canonicalized")

    # If a cache row exists and unexpired, return cached canonical_smiles (cache_key)
    now_iso = now
    def _parse_dt(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s) if isinstance(s, str) else None
        except Exception:
            return None

    cache_row = None
    for r in md:
        if not isinstance(r, dict):
            continue
        if r.get("kind") != "SMILES_CACHE":
            continue
        if r.get("cache_key") != canonical:
            continue
        if r.get("status") != "active":
            continue
        exp = _parse_dt(r.get("expires_at"))
        if exp is None or exp <= now_dt:
            continue
        cache_row = r
        break

    # Upsert cache row to record canonicalization (even if no payload yet)
    # expires_at in the future: 7 days
    expires = (now_dt + datetime.timedelta(days=7)).replace(microsecond=0).isoformat() + "Z"

    def _ulid_like():
        # Simple sortable id: time-based + random
        import random, string
        return "01" + now_dt.strftime("%y%m%d%H%M%S") + "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(10))

    updated = False
    if cache_row is None:
        # ensure uniqueness kind+cache_key by updating existing (even expired) if found
        existing_idx = None
        for i, r in enumerate(md):
            if isinstance(r, dict) and r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == canonical:
                existing_idx = i
                break
        if existing_idx is not None:
            r = md[existing_idx]
            if not isinstance(r, dict):
                r = {}
            r["kind"] = "SMILES_CACHE"
            r["cache_key"] = canonical
            r["expires_at"] = expires
            r["status"] = "active"
            r["updated_at"] = now_iso
            r.setdefault("created_at", now_iso)
            r.setdefault("cache_payload", {})
            md[existing_idx] = r
            updated = True
        else:
            md.append({
                "id": _ulid_like(),
                "kind": "SMILES_CACHE",
                "cache_key": canonical,
                "cache_payload": {},
                "expires_at": expires,
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso
            })
            updated = True
    else:
        # refresh expiry
        cache_row["expires_at"] = expires
        cache_row["updated_at"] = now_iso
        updated = True

    if updated:
        _save("service_metadata.json", md)

    _append_log("example_canonicalizeSmiles", "ok")
    return {"canonical_smiles": canonical}

def example_chemblDescriptors(smiles, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _find_log_collection():
        for fn in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _append_log(endpoint, status, credential_used=None, error_code=None):
        fn = _find_log_collection()
        if not fn:
            return
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + str(int(time.time() * 1000)),
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_used": credential_used,
            "error_code": error_code
        })
        _save(fn, logs)

    # ---- Validation ----
    if not isinstance(smiles, str):
        _append_log("example_chemblDescriptors", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "smiles must be a string")
    raw = smiles.strip()
    if not raw:
        _append_log("example_chemblDescriptors", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "smiles is required")

    # ---- Minimal canonicalization + validity check ----
    def _canonicalize(s):
        if any(ord(c) < 32 for c in s):
            return None
        if len(s) > 20000:
            return None
        bal = 0
        for c in s:
            if c == "[":
                bal += 1
            elif c == "]":
                bal -= 1
                if bal < 0:
                    return None
        if bal != 0:
            return None
        s2 = re.sub(r"\s+", "", s)
        if not s2:
            return None
        digest = hashlib.sha256(s2.encode("utf-8")).hexdigest()
        return f"CANON:{digest}:{s2}", s2

    canon_pair = _canonicalize(raw)
    if canon_pair is None:
        _append_log("example_chemblDescriptors", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "smiles cannot be parsed as a structure")
    canonical_key, norm_smiles = canon_pair

    # ---- Quota enforcement (if a log collection exists) ----
    # Soft compute quota: max 200 descriptor computations per rolling day (per datastore).
    log_fn = None
    for fn in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
        if os.path.exists(os.path.join(_DB, fn)):
            log_fn = fn
            break
    if log_fn:
        logs = _load(log_fn)
        if isinstance(logs, list):
            cutoff = now_dt - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != "example_chemblDescriptors":
                    continue
                ts = r.get("timestamp")
                try:
                    if isinstance(ts, str) and ts.endswith("Z"):
                        ts_dt = datetime.datetime.fromisoformat(ts[:-1])
                    else:
                        ts_dt = datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
                except Exception:
                    ts_dt = None
                if ts_dt and ts_dt >= cutoff and r.get("status") == "ok":
                    cnt += 1
            if cnt >= 200:
                _append_log("example_chemblDescriptors", "error", error_code="QUOTA_EXCEEDED")
                return _err("QUOTA_EXCEEDED", "Descriptor compute limit reached for the current period")

    # ---- Cache (service_metadata kind=SMILES_CACHE, cache_payload.chembl_descriptors) ----
    md = _load("service_metadata.json")
    if not isinstance(md, list):
        _append_log("example_chemblDescriptors", "error", error_code="INTERNAL_ERROR")
        return _err("INTERNAL_ERROR", "service_metadata store is corrupted")

    def _parse_dt(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s) if isinstance(s, str) else None
        except Exception:
            return None

    cache_idx = None
    for i, r in enumerate(md):
        if not isinstance(r, dict):
            continue
        if r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == canonical_key:
            cache_idx = i
            break

    payload = None
    if cache_idx is not None:
        r = md[cache_idx]
        if isinstance(r, dict) and r.get("status") == "active":
            exp = _parse_dt(r.get("expires_at"))
            if exp and exp > now_dt:
                cp = r.get("cache_payload")
                if isinstance(cp, dict) and isinstance(cp.get("chembl_descriptors"), dict):
                    payload = cp["chembl_descriptors"]

    if payload is None:
        # ---- Compute descriptors (offline approximation) ----
        # Provide stable numeric fields typical of ChEMBL descriptors, derived from string features.
        try:
            length = len(norm_smiles)
            heavy_like = sum(1 for c in norm_smiles if c.isalpha() and c.isupper() and c not in ("H",))
            aromatic_like = sum(1 for c in norm_smiles if c.islower())
            rings_like = norm_smiles.count("1") + norm_smiles.count("2") + norm_smiles.count("3")
            hetero_like = sum(norm_smiles.count(x) for x in ("N", "O", "S", "P", "F", "Cl", "Br", "I"))
            charge_like = norm_smiles.count("+") - norm_smiles.count("-")
            hbd_like = norm_smiles.count("N") + norm_smiles.count("O")  # crude
            hba_like = norm_smiles.count("N") + norm_smiles.count("O") + norm_smiles.count("S")  # crude
            # pseudo properties
            mw_like = round(12.0 * heavy_like + 1.0 * length, 3)
            alogp_like = round((aromatic_like * 0.1) + (rings_like * 0.05) - (hetero_like * 0.07), 3)
            psa_like = round((hba_like * 17.0) + (hbd_like * 5.0), 3)

            payload = {
                "canonical_smiles": canonical_key,
                "mw": mw_like,
                "alogp": alogp_like,
                "psa": psa_like,
                "hbd": int(hbd_like),
                "hba": int(hba_like),
                "rtb": int(norm_smiles.count("-")),  # crude rotatable bonds surrogate
                "aromatic_atoms": int(aromatic_like),
                "heavy_atoms": int(heavy_like),
                "net_charge": int(charge_like),
                "rings": int(rings_like // 2),
            }
        except Exception:
            _append_log("example_chemblDescriptors", "error", error_code="INTERNAL_ERROR")
            return _err("INTERNAL_ERROR", "Unexpected computation failure")

        # upsert cache with payload
        expires = (now_dt + datetime.timedelta(days=7)).replace(microsecond=0).isoformat() + "Z"

        def _ulid_like():
            import random, string
            return "01" + now_dt.strftime("%y%m%d%H%M%S") + "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(10))

        if cache_idx is None:
            md.append({
                "id": _ulid_like(),
                "kind": "SMILES_CACHE",
                "cache_key": canonical_key,
                "cache_payload": {"chembl_descriptors": payload},
                "expires_at": expires,
                "status": "active",
                "created_at": now,
                "updated_at": now
            })
        else:
            r = md[cache_idx]
            if not isinstance(r, dict):
                r = {}
            r["kind"] = "SMILES_CACHE"
            r["cache_key"] = canonical_key
            r["status"] = "active"
            r["expires_at"] = expires
            r["updated_at"] = now
            r.setdefault("created_at", now)
            cp = r.get("cache_payload")
            if not isinstance(cp, dict):
                cp = {}
            cp["chembl_descriptors"] = payload
            r["cache_payload"] = cp
            md[cache_idx] = r

        _save("service_metadata.json", md)

    _append_log("example_chemblDescriptors", "ok")
    return {"descriptors": payload}

def example_description_utils(chembl_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _find_log_collection():
        for fn in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _append_log(endpoint, status, credential_used=None, error_code=None):
        fn = _find_log_collection()
        if not fn:
            return
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + str(int(time.time() * 1000)),
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_used": credential_used,
            "error_code": error_code
        })
        _save(fn, logs)

    # ---- Validate ----
    if not isinstance(chembl_id, str):
        _append_log("example_description_utils", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chembl_id must be a string")
    cid = chembl_id.strip()
    if not cid:
        _append_log("example_description_utils", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chembl_id is required")
    # ChEMBL identifier format (typical): CHEMBL + digits
    if not re.fullmatch(r"CHEMBL\d+", cid, flags=re.IGNORECASE):
        _append_log("example_description_utils", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chembl_id is not a valid ChEMBL identifier format", chembl_id=cid)

    # ---- Quota enforcement (if log collection exists) ----
    # Soft read quota: max 5000 description reads per rolling day (per datastore).
    log_fn = None
    for fn in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
        if os.path.exists(os.path.join(_DB, fn)):
            log_fn = fn
            break
    if log_fn:
        logs = _load(log_fn)
        if isinstance(logs, list):
            cutoff = now_dt - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != "example_description_utils":
                    continue
                ts = r.get("timestamp")
                try:
                    if isinstance(ts, str) and ts.endswith("Z"):
                        ts_dt = datetime.datetime.fromisoformat(ts[:-1])
                    else:
                        ts_dt = datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
                except Exception:
                    ts_dt = None
                if ts_dt and ts_dt >= cutoff and r.get("status") == "ok":
                    cnt += 1
            if cnt >= 5000:
                _append_log("example_description_utils", "error", error_code="QUOTA_EXCEEDED")
                return _err("QUOTA_EXCEEDED", "Read limit exceeded for the current period")

    # ---- Lookup ----
    entities = _load("chembl_entities.json")
    if not isinstance(entities, list):
        _append_log("example_description_utils", "error", error_code="INTERNAL_ERROR")
        return _err("INTERNAL_ERROR", "chembl_entities store is corrupted")

    target = None
    cid_upper = cid.upper()
    for r in entities:
        if not isinstance(r, dict):
            continue
        if isinstance(r.get("chembl_id"), str) and r["chembl_id"].upper() == cid_upper:
            target = r
            break

    if target is None:
        _append_log("example_description_utils", "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "ChEMBL ID not found", chembl_id=cid_upper)

    desc = target.get("description_text")
    # Business rules say: returns description_text; tool says NOT_FOUND if ID does not exist.
    # If ID exists but description_text is null, return empty result.
    _append_log("example_description_utils", "ok")
    if desc is None:
        return {"chembl_id": target.get("chembl_id"), "description": None}
    return {"chembl_id": target.get("chembl_id"), "description": desc}

def example_descriptors(smiles, **_extra):
    import json, os, datetime, time, re, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "example_descriptors"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_ulid():
        # Not a real ULID, but stable unique id with similar shape; sufficient for local datastore.
        ts = int(time.time() * 1000)
        rand = os.urandom(10).hex()
        return f"01{ts:010d}{rand}"[:26]

    def _log(status, credential=None, error_code=None):
        # No request-log collection in schema; dynamics recorded via SMILES_CACHE metadata rows (reads/mutations update updated_at).
        # Still return a structured envelope only.
        return

    def _validate_smiles(s):
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", "smiles must be a string")
        s2 = s.strip()
        if not s2:
            return _err("VALIDATION_ERROR", "smiles is required")
        # Offline "parseability" heuristic (can't run RDKit). Reject clearly invalid.
        if len(s2) > 20000:
            return _err("VALIDATION_ERROR", "smiles too long")
        if any(ch in s2 for ch in ["\x00", "\n", "\r", "\t"]):
            return _err("VALIDATION_ERROR", "smiles contains control characters")
        allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789[]()=#@+-\\/%.:*,$")
        # allow whitespace inside? no: after strip, reject any remaining spaces
        if " " in s2:
            return _err("VALIDATION_ERROR", "smiles contains spaces")
        if any(ch not in allowed for ch in s2):
            return _err("VALIDATION_ERROR", "smiles contains invalid characters")
        # balanced parentheses
        bal = 0
        for ch in s2:
            if ch == "(":
                bal += 1
            elif ch == ")":
                bal -= 1
                if bal < 0:
                    return _err("VALIDATION_ERROR", "smiles has unbalanced parentheses")
        if bal != 0:
            return _err("VALIDATION_ERROR", "smiles has unbalanced parentheses")
        return None

    def _canonicalize_smiles(s):
        # Deterministic canonicalization surrogate: strip and collapse backslashes, keep case,
        # remove atom mapping digits after ':' (common), and normalize multiple slashes.
        s = s.strip()
        s = re.sub(r":\d+", "", s)
        s = re.sub(r"/{2,}", "/", s)
        s = re.sub(r"\\{2,}", "\\\\", s)
        return s

    def _quota_check_and_burn(kind_key):
        # Compute quota via service_metadata rows of kind='SMILES_CACHE' updated/created today.
        # Limit: 1000 computes/day across all utilities; do not count cache hits.
        limit = 1000
        md = _load("service_metadata.json")
        now = datetime.datetime.utcnow()
        today = now.date()
        used = 0
        for r in md:
            if r.get("kind") != "SMILES_CACHE":
                continue
            # count only rows that recorded compute usage marker in cache_payload._usage
            payload = r.get("cache_payload") or {}
            usage = payload.get("_usage") or {}
            # usage is dict {"compute_events":[{"k":..., "ts":...}, ...]} or {"count":int, "date":...}
            # Support both; prefer events.
            ev = usage.get("compute_events")
            if isinstance(ev, list):
                for e in ev:
                    ts = _parse_dt(e.get("ts") if isinstance(e, dict) else None)
                    if ts and ts.date() == today:
                        used += 1
            else:
                d = usage.get("date")
                if isinstance(d, str):
                    try:
                        ddt = datetime.date.fromisoformat(d)
                    except Exception:
                        ddt = None
                    if ddt == today:
                        c = usage.get("count")
                        if isinstance(c, int) and c > 0:
                            used += c
        if used >= limit:
            return _err("QUOTA_EXCEEDED", "Daily utility compute quota exceeded", limit=limit, used=used)
        return None

    def _cache_get(cache_key):
        md = _load("service_metadata.json")
        now = datetime.datetime.utcnow()
        for r in md:
            if r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == cache_key and r.get("status") == "active":
                exp = _parse_dt(r.get("expires_at"))
                if exp and exp > now:
                    return r
        return None

    def _cache_upsert(cache_key, mutate_fn):
        md = _load("service_metadata.json")
        now = datetime.datetime.utcnow()
        now_iso = _now_iso()
        exp_iso = (now + datetime.timedelta(days=7)).replace(microsecond=0).isoformat() + "Z"
        found_idx = None
        for i, r in enumerate(md):
            if r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == cache_key:
                found_idx = i
                break
        if found_idx is None:
            row = {
                "id": _new_ulid(),
                "kind": "SMILES_CACHE",
                "chembl_version": None,
                "release_date": None,
                "service_name": None,
                "service_status": None,
                "message": None,
                "cache_key": cache_key,
                "cache_payload": {},
                "expires_at": exp_iso,
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            row = mutate_fn(row, creating=True)
            if isinstance(row, dict) and row.get("error"):
                return row
            md.append(row)
        else:
            row = md[found_idx]
            # revive if expired but still present
            row["status"] = "active"
            row["expires_at"] = exp_iso
            row["updated_at"] = now_iso
            row = mutate_fn(row, creating=False)
            if isinstance(row, dict) and row.get("error"):
                return row
            md[found_idx] = row
        _save("service_metadata.json", md)
        return row

    # Validate
    ve = _validate_smiles(smiles)
    if ve:
        _log("error", error_code="VALIDATION_ERROR")
        return ve

    canonical = _canonicalize_smiles(smiles)

    # Cache hit?
    cache_row = _cache_get(canonical)
    if cache_row:
        payload = cache_row.get("cache_payload") or {}
        desc = payload.get("descriptors")
        if isinstance(desc, dict):
            _log("ok")
            return {"smiles": smiles, "canonical_smiles": canonical, "descriptors": desc, "cached": True}

    # Quota (compute) check
    qe = _quota_check_and_burn("descriptors")
    if qe:
        _log("error", error_code="QUOTA_EXCEEDED")
        return qe

    # Compute descriptors (heuristic/offline)
    try:
        s = canonical
        # simple token-like counts
        atom_symbols = re.findall(r"\[.*?\]|Br|Cl|Si|Na|Ca|Li|Mg|Al|Fe|Zn|Cu|Mn|Hg|Sn|Ag|Au|Pt|Pd|I|B|C|N|O|P|S|F|K|H", s)
        # atoms not in brackets from aromatic lower-case
        atom_symbols += re.findall(r"(?<![A-Za-z])[cnopsb]", s)
        atom_count = len(atom_symbols)
        ring_digits = re.findall(r"(?<!%)\d", s) + re.findall(r"%\d\d", s)
        ring_count = len(ring_digits) // 2 if len(ring_digits) >= 2 else 0
        hetero = sum(1 for a in atom_symbols if a.strip("[]").lower() in ("n", "o", "s", "p", "f", "cl", "br", "i"))
        halogens = sum(1 for a in atom_symbols if a.strip("[]").lower() in ("f", "cl", "br", "i"))
        brackets = s.count("[")
        branches = s.count("(")
        double_bonds = s.count("=")
        triple_bonds = s.count("#")
        aromatic = sum(1 for a in atom_symbols if a.strip("[]").islower())
        # crude MW approximation: typical organic avg 12-14 per atom; better: count C/N/O/S/halogens
        sym = [a.strip("[]") for a in atom_symbols]
        def _cnt(xset):
            return sum(1 for a in sym if a in xset)
        c = _cnt({"C", "c"})
        n = _cnt({"N", "n"})
        o = _cnt({"O", "o"})
        p = _cnt({"P", "p"})
        s_cnt = _cnt({"S", "s"})
        f = _cnt({"F"})
        cl = _cnt({"Cl"})
        br = _cnt({"Br"})
        i = _cnt({"I"})
        # approximate weights
        mw = (c * 12.011 + n * 14.007 + o * 15.999 + p * 30.974 + s_cnt * 32.06 +
              f * 18.998 + cl * 35.45 + br * 79.904 + i * 126.904)
        # pseudo logP heuristic
        xlogp = max(-2.0, min(10.0, (c * 0.54 + aromatic * 0.1 + halogens * 0.23 - hetero * 0.6)))
        tpsa = max(0.0, (n * 25.0 + o * 17.0 + s_cnt * 25.0 + p * 17.0))
        hbd = n + o  # very rough
        hba = max(0, (n + o + s_cnt + p))
        rot_bonds = max(0, (atom_count - ring_count * 2 - branches - (aromatic // 2) - 1))
        descriptors = {
            "atom_count": atom_count,
            "ring_count": ring_count,
            "hetero_atom_count": hetero,
            "halogen_count": halogens,
            "bracket_atom_count": brackets,
            "branch_count": branches,
            "double_bond_count": double_bonds,
            "triple_bond_count": triple_bonds,
            "aromatic_atom_count": aromatic,
            "molecular_weight": round(mw, 3),
            "xlogp": round(xlogp, 3),
            "tpsa": round(tpsa, 3),
            "hbd": int(hbd),
            "hba": int(hba),
            "rotatable_bond_count": int(rot_bonds),
        }
    except Exception:
        _log("error", error_code="INTERNAL_ERROR")
        return _err("INTERNAL_ERROR", "Unexpected computation failure")

    # Persist cache with usage marker
    def _mut(row, creating):
        payload = row.get("cache_payload") or {}
        payload["descriptors"] = descriptors
        usage = payload.get("_usage") or {}
        ev = usage.get("compute_events")
        if not isinstance(ev, list):
            ev = []
        ev.append({"k": "descriptors", "ts": _now_iso()})
        usage["compute_events"] = ev
        payload["_usage"] = usage
        row["cache_payload"] = payload
        return row

    up = _cache_upsert(canonical, _mut)
    if isinstance(up, dict) and up.get("error"):
        _log("error", error_code=up["error"].get("code"))
        return up

    _log("ok")
    return {"smiles": smiles, "canonical_smiles": canonical, "descriptors": descriptors, "cached": False}

def example_getParent(chembl_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _valid_chembl_id(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        if not s:
            return False
        return re.fullmatch(r"CHEMBL\d+", s) is not None

    # Validate
    if not isinstance(chembl_id, str):
        return _err("VALIDATION_ERROR", "chembl_id must be a string")
    chembl_id = chembl_id.strip()
    if not chembl_id:
        return _err("VALIDATION_ERROR", "chembl_id is required")
    if not _valid_chembl_id(chembl_id):
        return _err("VALIDATION_ERROR", "chembl_id is not a valid ChEMBL identifier format")

    ents = _load("chembl_entities.json")
    row = None
    for e in ents:
        if e.get("chembl_id") == chembl_id:
            row = e
            break
    if row is None:
        return _err("NOT_FOUND", "ChEMBL ID not found", chembl_id=chembl_id)

    parent_id = row.get("parent_entity_id")
    if not parent_id:
        return _err("NOT_FOUND", "No parent relationship available for this entity", chembl_id=chembl_id)

    parent = None
    for e in ents:
        if e.get("id") == parent_id:
            parent = e
            break
    if parent is None:
        # broken reference
        return _err("NOT_FOUND", "Parent entity not found", parent_entity_id=parent_id)

    return {"chembl_id": chembl_id, "parent_chembl_id": parent.get("chembl_id")}

def example_highlightSmilesFragmentSvg(smiles, fragment, **_extra):
    import json, os, datetime, time, random, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "example_highlightSmilesFragmentSvg"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _get_service_status_row(meta_rows):
        for r in meta_rows:
            if isinstance(r, dict) and r.get("kind") == "SERVICE_STATUS" and r.get("status") == "active":
                return r
        return None

    def _ensure_service_row(meta_rows):
        sr = _get_service_status_row(meta_rows)
        if sr is None:
            sr = {
                "id": f"chs_meta_{int(time.time()*1000)}{random.randint(100,999)}",
                "kind": "SERVICE_STATUS",
                "service_status": "ok",
                "service_name": "ChEMBL Server",
                "message": "Auto-created service status row",
                "status": "active",
                "cache_payload": {},
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            meta_rows.append(sr)
        if not isinstance(sr.get("cache_payload"), dict):
            sr["cache_payload"] = {}
        cp = sr["cache_payload"]
        if not isinstance(cp.get("request_log"), list):
            cp["request_log"] = []
        if not isinstance(cp.get("quota"), dict):
            # Separate compute quota for depictions
            cp["quota"] = {"window_seconds": 60, "max_requests": 120, "max_compute": 200}
        if not isinstance(cp.get("compute_log"), list):
            cp["compute_log"] = []
        return sr

    def _check_rate_limit(service_row):
        cp = service_row.get("cache_payload") if isinstance(service_row.get("cache_payload"), dict) else {}
        quota = cp.get("quota") if isinstance(cp.get("quota"), dict) else {}
        window_seconds = quota.get("window_seconds", 60)
        max_requests = quota.get("max_requests", 120)
        if not isinstance(window_seconds, int) or window_seconds <= 0:
            window_seconds = 60
        if not isinstance(max_requests, int) or max_requests <= 0:
            max_requests = 120

        req_log = cp.get("request_log", [])
        if not isinstance(req_log, list):
            return None

        now = datetime.datetime.utcnow()
        start = now - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for rec in req_log:
            if not isinstance(rec, dict):
                continue
            ts = _parse_ts(rec.get("timestamp"))
            if ts is not None and ts >= start:
                cnt += 1
        if cnt >= max_requests:
            return _err("RATE_LIMIT", "Too many requests in the current time window.", window_seconds=window_seconds, max_requests=max_requests)
        return None

    def _check_compute_quota(service_row):
        cp = service_row.get("cache_payload") if isinstance(service_row.get("cache_payload"), dict) else {}
        quota = cp.get("quota") if isinstance(cp.get("quota"), dict) else {}
        window_seconds = quota.get("window_seconds", 60)
        max_compute = quota.get("max_compute", 200)
        if not isinstance(window_seconds, int) or window_seconds <= 0:
            window_seconds = 60
        if not isinstance(max_compute, int) or max_compute <= 0:
            max_compute = 200

        clog = cp.get("compute_log", [])
        if not isinstance(clog, list):
            return None

        now = datetime.datetime.utcnow()
        start = now - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for rec in clog:
            if not isinstance(rec, dict):
                continue
            ts = _parse_ts(rec.get("timestamp"))
            if ts is not None and ts >= start:
                cnt += 1
        if cnt >= max_compute:
            return _err("QUOTA_EXCEEDED", "Utility/depiction compute quota exceeded.", window_seconds=window_seconds, max_compute=max_compute)
        return None

    def _append_req(meta_rows, service_row, status, error_code=None):
        cp = service_row["cache_payload"]
        rec = {
            "id": f"req_{int(time.time()*1000)}{random.randint(100,999)}",
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_used": None,
        }
        if error_code:
            rec["error_code"] = error_code
        cp["request_log"].append(rec)
        service_row["updated_at"] = _now_iso()
        _save("service_metadata.json", meta_rows)

    def _append_compute(meta_rows, service_row, cache_hit):
        cp = service_row["cache_payload"]
        cp["compute_log"].append(
            {
                "id": f"cmp_{int(time.time()*1000)}{random.randint(100,999)}",
                "timestamp": _now_iso(),
                "endpoint": endpoint,
                "cache_hit": bool(cache_hit),
            }
        )
        service_row["updated_at"] = _now_iso()
        _save("service_metadata.json", meta_rows)

    def _canonicalize_smiles(s):
        # Offline, standard-library canonicalization surrogate:
        # normalize whitespace and use stable key hash for caching.
        s2 = " ".join(s.strip().split())
        return s2

    def _looks_like_id(x):
        return isinstance(x, str) and (x.startswith("chs_ent_") or x.startswith("CHEMBL"))

    def _resolve_fragment(fragment_value, entities):
        # fragment may be an internal entity id or a public chembl_id.
        if fragment_value.startswith("chs_ent_"):
            for e in entities:
                if isinstance(e, dict) and e.get("id") == fragment_value:
                    return e
            return None
        # treat as chembl_id
        for e in entities:
            if isinstance(e, dict) and e.get("chembl_id") == fragment_value:
                return e
        return None

    def _simple_svg(smiles_text, highlight_text):
        # Produce deterministic SVG string; highlight rendered as a labeled box.
        esc = lambda x: (x.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;"))
        s = esc(smiles_text)
        h = esc(highlight_text)
        width = 720
        height = 120
        return (
            f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">'
            f'<rect x="0" y="0" width="{width}" height="{height}" fill="white" />'
            f'<text x="20" y="40" font-family="monospace" font-size="16" fill="#111">SMILES: {s}</text>'
            f'<rect x="16" y="58" width="{width-32}" height="44" rx="6" fill="#fff7cc" stroke="#d4a300" />'
            f'<text x="24" y="86" font-family="monospace" font-size="16" fill="#111">HIGHLIGHT: {h}</text>'
            f"</svg>"
        )

    # Validate inputs
    if smiles is None or not isinstance(smiles, str):
        meta = _load("service_metadata.json")
        if not isinstance(meta, list):
            meta = []
        sr = _ensure_service_row(meta)
        rl = _check_rate_limit(sr)
        if rl:
            _append_req(meta, sr, "error", "RATE_LIMIT")
            return rl
        _append_req(meta, sr, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "smiles is required and must be a string.", smiles=smiles)
    if fragment is None or not isinstance(fragment, str):
        meta = _load("service_metadata.json")
        if not isinstance(meta, list):
            meta = []
        sr = _ensure_service_row(meta)
        rl = _check_rate_limit(sr)
        if rl:
            _append_req(meta, sr, "error", "RATE_LIMIT")
            return rl
        _append_req(meta, sr, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fragment is required and must be a string.", fragment=fragment)

    smiles = smiles.strip()
    fragment = fragment.strip()
    if not smiles:
        meta = _load("service_metadata.json")
        if not isinstance(meta, list):
            meta = []
        sr = _ensure_service_row(meta)
        rl = _check_rate_limit(sr)
        if rl:
            _append_req(meta, sr, "error", "RATE_LIMIT")
            return rl
        _append_req(meta, sr, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "smiles must be non-empty.", smiles=smiles)
    if not fragment:
        meta = _load("service_metadata.json")
        if not isinstance(meta, list):
            meta = []
        sr = _ensure_service_row(meta)
        rl = _check_rate_limit(sr)
        if rl:
            _append_req(meta, sr, "error", "RATE_LIMIT")
            return rl
        _append_req(meta, sr, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fragment must be non-empty.", fragment=fragment)

    # Minimal SMILES sanity (avoid rejecting valid strings used in tests)
    if any(ch in smiles for ch in ["\n", "\r", "\x00"]):
        meta = _load("service_metadata.json")
        if not isinstance(meta, list):
            meta = []
        sr = _ensure_service_row(meta)
        rl = _check_rate_limit(sr)
        if rl:
            _append_req(meta, sr, "error", "RATE_LIMIT")
            return rl
        _append_req(meta, sr, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "SMILES cannot be parsed (contains invalid control characters).", rule="smiles_must_be_parseable")

    # Logging/rate limit
    meta = _load("service_metadata.json")
    if not isinstance(meta, list):
        meta = []
    sr = _ensure_service_row(meta)
    rl = _check_rate_limit(sr)
    if rl:
        _append_req(meta, sr, "error", "RATE_LIMIT")
        return rl

    # Resolve fragment to something interpretable: entity id or chembl_id must exist
    entities = _load("chembl_entities.json")
    if not isinstance(entities, list):
        entities = []
    frag_ent = _resolve_fragment(fragment, entities) if _looks_like_id(fragment) else None
    if frag_ent is None:
        # Fragment could also be a literal substructure text; allow it without requiring entity existence
        # as long as it appears as a substring token-ish in the SMILES text.
        if fragment not in smiles:
            _append_req(meta, sr, "error", "VALIDATION_ERROR")
            return _err(
                "VALIDATION_ERROR",
                "fragment could not be interpreted or matched for highlighting in the provided SMILES.",
                rule="fragment_must_be_interpretable_or_match_input",
                fragment=fragment,
            )
        frag_label = fragment
    else:
        frag_label = frag_ent.get("chembl_id") or frag_ent.get("id") or fragment

    canonical_smiles = _canonicalize_smiles(smiles)

    # Cache lookup/upsert in service_metadata(kind='SMILES_CACHE')
    service_meta = meta  # already loaded
    now_dt = datetime.datetime.utcnow()

    cache_row = None
    for r in service_meta:
        if not isinstance(r, dict):
            continue
        if r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == canonical_smiles:
            cache_row = r
            break

    def _is_unexpired(row):
        if not isinstance(row, dict):
            return False
        if row.get("status") != "active":
            return False
        exp = _parse_ts(row.get("expires_at"))
        return exp is not None and exp > now_dt

    cache_hit = False
    payload = {}
    if cache_row and isinstance(cache_row.get("cache_payload"), dict) and _is_unexpired(cache_row):
        payload = cache_row["cache_payload"]
        cache_hit = True

    cache_key = hashlib.sha256((canonical_smiles + "|" + fragment).encode("utf-8")).hexdigest()
    if cache_hit and isinstance(payload.get("highlight_svgs"), dict):
        existing = payload["highlight_svgs"].get(cache_key)
        if isinstance(existing, str) and existing:
            _append_compute(service_meta, sr, cache_hit=True)
            _append_req(service_meta, sr, "ok", None)
            return {"smiles": smiles, "canonical_smiles": canonical_smiles, "fragment": fragment, "svg": existing, "cached": True}

    # Need to compute -> enforce compute quota
    cq = _check_compute_quota(sr)
    if cq:
        _append_req(service_meta, sr, "error", "QUOTA_EXCEEDED")
        return cq

    # "Compute" svg (offline deterministic depiction)
    svg = _simple_svg(smiles, frag_label)

    # Upsert cache row (unexpired)
    expires_at = (now_dt + datetime.timedelta(days=7)).replace(microsecond=0).isoformat() + "Z"
    if cache_row is None or not isinstance(cache_row, dict):
        cache_row = {
            "id": f"chs_meta_{int(time.time()*1000)}{random.randint(100,999)}",
            "kind": "SMILES_CACHE",
            "cache_key": canonical_smiles,
            "cache_payload": {},
            "expires_at": expires_at,
            "status": "active",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        service_meta.append(cache_row)
    else:
        # If expired, transition to active by creating a new row is more realistic; but schema transitions don't allow.
        # Therefore, only refresh if currently active or leave as-is if expired and create a new row with unique(kind, cache_key) constraint.
        if cache_row.get("status") == "expired":
            # Create a new cache row with same key would violate unique(kind, cache_key); so revive is impossible via transitions.
            # Instead, keep the existing row active by not forcing transition; refresh expiry/payload regardless if expired.
            cache_row["status"] = "active"
        cache_row["expires_at"] = expires_at
        cache_row["updated_at"] = _now_iso()
        if not isinstance(cache_row.get("cache_payload"), dict):
            cache_row["cache_payload"] = {}

    cp = cache_row["cache_payload"]
    if not isinstance(cp.get("highlight_svgs"), dict):
        cp["highlight_svgs"] = {}
    cp["highlight_svgs"][cache_key] = svg
    cache_row["updated_at"] = _now_iso()
    _save("service_metadata.json", service_meta)

    _append_compute(service_meta, sr, cache_hit=False)
    _append_req(service_meta, sr, "ok", None)
    return {"smiles": smiles, "canonical_smiles": canonical_smiles, "fragment": fragment, "svg": svg, "cached": False}

def example_inchi2inchiKey(inchi, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_ulid():
        ts = int(time.time() * 1000)
        rand = os.urandom(10).hex()
        return f"01{ts:010d}{rand}"[:26]

    def _quota_check():
        limit = 1000
        md = _load("service_metadata.json")
        now = datetime.datetime.utcnow()
        today = now.date()
        used = 0
        for r in md:
            if r.get("kind") != "SMILES_CACHE":
                continue
            payload = r.get("cache_payload") or {}
            usage = payload.get("_usage") or {}
            ev = usage.get("compute_events")
            if isinstance(ev, list):
                for e in ev:
                    if not isinstance(e, dict):
                        continue
                    ts = _parse_dt(e.get("ts"))
                    if ts and ts.date() == today:
                        used += 1
            else:
                d = usage.get("date")
                if isinstance(d, str):
                    try:
                        ddt = datetime.date.fromisoformat(d)
                    except Exception:
                        ddt = None
                    if ddt == today:
                        c = usage.get("count")
                        if isinstance(c, int) and c > 0:
                            used += c
        if used >= limit:
            return _err("QUOTA_EXCEEDED", "Daily utility compute quota exceeded", limit=limit, used=used)
        return None

    def _cache_get(cache_key):
        md = _load("service_metadata.json")
        now = datetime.datetime.utcnow()
        for r in md:
            if r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == cache_key and r.get("status") == "active":
                exp = _parse_dt(r.get("expires_at"))
                if exp and exp > now:
                    return r
        return None

    def _cache_upsert(cache_key, mutate_fn):
        md = _load("service_metadata.json")
        now = datetime.datetime.utcnow()
        now_iso = _now_iso()
        exp_iso = (now + datetime.timedelta(days=7)).replace(microsecond=0).isoformat() + "Z"
        idx = None
        for i, r in enumerate(md):
            if r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == cache_key:
                idx = i
                break
        if idx is None:
            row = {
                "id": _new_ulid(),
                "kind": "SMILES_CACHE",
                "chembl_version": None,
                "release_date": None,
                "service_name": None,
                "service_status": None,
                "message": None,
                "cache_key": cache_key,
                "cache_payload": {},
                "expires_at": exp_iso,
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            row = mutate_fn(row, creating=True)
            if isinstance(row, dict) and row.get("error"):
                return row
            md.append(row)
        else:
            row = md[idx]
            row["status"] = "active"
            row["expires_at"] = exp_iso
            row["updated_at"] = now_iso
            row = mutate_fn(row, creating=False)
            if isinstance(row, dict) and row.get("error"):
                return row
            md[idx] = row
        _save("service_metadata.json", md)
        return row

    # Validate
    if not isinstance(inchi, str):
        return _err("VALIDATION_ERROR", "inchi must be a string")
    inchi = inchi.strip()
    if not inchi:
        return _err("VALIDATION_ERROR", "inchi is required")
    # Basic InChI format check
    if not (inchi.startswith("InChI=") or inchi.startswith("InChI=1S/") or inchi.startswith("InChI=1/")):
        return _err("VALIDATION_ERROR", "inchi is not a valid/parseable InChI")
    if len(inchi) > 20000:
        return _err("VALIDATION_ERROR", "inchi too long")
    if any(ch in inchi for ch in ["\x00", "\n", "\r"]):
        return _err("VALIDATION_ERROR", "inchi contains control characters")

    # Cache by inchi hash as cache_key (schema uses cache_key field; not limited to smiles).
    cache_key = "INCHIKEY|" + hashlib.sha256(inchi.encode("utf-8")).hexdigest()

    cache_row = _cache_get(cache_key)
    if cache_row:
        payload = cache_row.get("cache_payload") or {}
        ik = payload.get("inchi_key")
        if isinstance(ik, str) and ik:
            return {"inchi": inchi, "inchi_key": ik, "cached": True}

    qe = _quota_check()
    if qe:
        return qe

    # Deterministic offline InChIKey-like (not chemically correct): 27 chars with dash at pos 15.
    try:
        h = hashlib.sha256(inchi.encode("utf-8")).hexdigest().upper()
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        def base26(n, length):
            out = []
            for _ in range(length):
                out.append(alphabet[n % 26])
                n //= 26
            return "".join(reversed(out))
        n1 = int(h[:16], 16)
        n2 = int(h[16:24], 16)
        n3 = int(h[24:28], 16)
        block1 = base26(n1, 14)
        block2 = base26(n2, 10)
        block3 = base26(n3, 1)
        inchi_key = f"{block1}-{block2}{block3}"
        # length 27 with one dash: 14 + 1 + 11 = 26? Actually block2+block3=11 => total 26; adjust to 27 by adding one char
        if len(inchi_key) == 26:
            inchi_key = inchi_key + "A"
        # ensure 27 or 28 allowed by schema constraint for compound_structures; here we target 27
        if len(inchi_key) not in (27, 28):
            inchi_key = (inchi_key + "A" * 28)[:27]
    except Exception:
        return _err("INTERNAL_ERROR", "Unexpected conversion failure")

    def _mut(row, creating):
        payload = row.get("cache_payload") or {}
        payload["inchi_key"] = inchi_key
        usage = payload.get("_usage") or {}
        ev = usage.get("compute_events")
        if not isinstance(ev, list):
            ev = []
        ev.append({"k": "inchi2inchikey", "ts": _now_iso()})
        usage["compute_events"] = ev
        payload["_usage"] = usage
        row["cache_payload"] = payload
        return row

    up = _cache_upsert(cache_key, _mut)
    if isinstance(up, dict) and up.get("error"):
        return up

    return {"inchi": inchi, "inchi_key": inchi_key, "cached": False}

def example_inchi2svg(inchi, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Simple ULID-like generator (time-ordered, base32-ish)
    def _ulid():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms
        out = []
        for _ in range(10):
            out.append(alphabet[t & 31])
            t >>= 5
        rand = int.from_bytes(os.urandom(10), "big")
        for _ in range(16):
            out.append(alphabet[rand & 31])
            rand >>= 5
        return "".join(reversed(out))

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(float(s))
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, latency_ms, meta=None):
        # Observable dynamics: store in service_metadata as kind='SERVICE_STATUS' message log (best available)
        rows = _load("service_metadata.json")
        ts = _now_iso()
        log_row = {
            "id": _ulid(),
            "kind": "SERVICE_STATUS",
            "chembl_version": None,
            "release_date": None,
            "service_name": "ChEMBL Server",
            "service_status": "ok" if status < 400 else "degraded",
            "message": json.dumps(
                {
                    "event": "request",
                    "endpoint": endpoint,
                    "status": status,
                    "latency_ms": latency_ms,
                    "timestamp": ts,
                    "meta": meta or {},
                },
                ensure_ascii=False,
            ),
            "cache_key": None,
            "cache_payload": None,
            "expires_at": None,
            "status": "active",
            "created_at": ts,
            "updated_at": ts,
        }
        rows.append(log_row)
        _save("service_metadata.json", rows)

    def _enforce_quota(endpoint):
        # Quota enforcement via request logs stored above.
        # Limits (service-side policy): 200 utility calls/day.
        rows = _load("service_metadata.json")
        now = datetime.datetime.utcnow()
        day_ago = now - datetime.timedelta(days=1)
        cnt = 0
        for r in rows:
            if r.get("kind") != "SERVICE_STATUS":
                continue
            msg = r.get("message")
            if not isinstance(msg, str):
                continue
            try:
                j = json.loads(msg)
            except Exception:
                continue
            if j.get("event") != "request":
                continue
            if j.get("endpoint") != endpoint:
                continue
            ts = j.get("timestamp")
            dt = _parse_dt(ts)
            if dt is None:
                continue
            if dt >= day_ago:
                cnt += 1
        if cnt >= 200:
            return _err("QUOTA_EXCEEDED", "Daily utility compute quota exceeded.", limit=200, window="24h")
        return None

    t0 = time.time()

    # Validate input
    if not isinstance(inchi, str) or not inchi.strip():
        latency = int((time.time() - t0) * 1000)
        _log("example_inchi2svg", 400, latency, {"error": "missing_inchi"})
        return _err("VALIDATION_ERROR", "`inchi` is required and must be a non-empty string.")
    inchi_s = inchi.strip()

    # Basic parse/format validation
    # Require "InChI=" prefix and version token like "1" or "1S"
    if not inchi_s.startswith("InChI="):
        latency = int((time.time() - t0) * 1000)
        _log("example_inchi2svg", 400, latency, {"error": "bad_inchi_prefix"})
        return _err("VALIDATION_ERROR", "`inchi` must start with 'InChI='.")
    # Must have at least one layer separator '/'
    if "/" not in inchi_s:
        latency = int((time.time() - t0) * 1000)
        _log("example_inchi2svg", 400, latency, {"error": "bad_inchi_layers"})
        return _err("VALIDATION_ERROR", "`inchi` is not parseable (missing layers).")
    m = re.match(r"^InChI=([0-9]+)(S)?/", inchi_s)
    if not m:
        latency = int((time.time() - t0) * 1000)
        _log("example_inchi2svg", 400, latency, {"error": "bad_inchi_version"})
        return _err("VALIDATION_ERROR", "`inchi` is not a valid InChI version header.")

    qerr = _enforce_quota("example_inchi2svg")
    if qerr:
        latency = int((time.time() - t0) * 1000)
        _log("example_inchi2svg", 429, latency, {"error": "quota"})
        return qerr

    # 1) Try cached svg_2d from compound_structures by matching inchi exactly
    compound_structures = _load("compound_structures.json")
    for cs in compound_structures:
        if cs.get("status") != "active":
            continue
        if cs.get("inchi") == inchi_s and isinstance(cs.get("svg_2d"), str) and cs.get("svg_2d"):
            latency = int((time.time() - t0) * 1000)
            _log("example_inchi2svg", 200, latency, {"cache": "compound_structures"})
            return {"svg": cs.get("svg_2d"), "cached": True}

    # 2) Try SMILES_CACHE: use inchi_key-like derived key from inchi
    # We can't compute a real InChIKey offline; use stable sha256-based surrogate keyed to InChI.
    key = "INCHI:" + hashlib.sha256(inchi_s.encode("utf-8")).hexdigest()
    service_metadata = _load("service_metadata.json")
    now_iso = _now_iso()
    now_dt = datetime.datetime.utcnow()
    cache_row = None
    for r in service_metadata:
        if r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == key:
