            break
    if cache_row:
        exp = _parse_dt(cache_row.get("expires_at"))
        if cache_row.get("status") == "active" and exp and exp > now_dt:
            payload = cache_row.get("cache_payload") if isinstance(cache_row.get("cache_payload"), dict) else {}
            svg = payload.get("svg_2d")
            if isinstance(svg, str) and svg:
                latency = int((time.time() - t0) * 1000)
                _log("example_inchi2svg", 200, latency, {"cache": "service_metadata"})
