        # Expire if needed
        if exp and exp <= now_dt and cache_row.get("status") == "active":
            # lifecycle transition active -> expired allowed
            cache_row["status"] = "expired"
            cache_row["updated_at"] = now_iso
            _save("service_metadata.json", service_metadata)

