    if cache_row and cache_row.get("kind") == "SMILES_CACHE" and cache_row.get("cache_key") == key:
        # Upsert if row is not expired? Real service might update; keep status active.
        cache_row["cache_payload"] = dict(cache_row.get("cache_payload") or {})
        cache_row["cache_payload"]["svg_2d"] = svg
        cache_row["expires_at"] = expires_iso
        cache_row["status"] = "active"
        cache_row["updated_at"] = now_iso
    else:
