                "expires_at": expires_iso,
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso,
            }
        )
    _save("service_metadata.json", service_metadata)

    latency = int((time.time() - t0) * 1000)
    _log("example_inchi2svg", 200, latency, {"cache": "miss_write"})
    return {"svg": svg, "cached": False}

def example_is3D(smiles, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")

    def _load(n):
        try:
