                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms
        out = []
        for _ in range(10):
            out.append(alphabet[t & 31])
            t >>= 5
        rand = int.from_bytes(os.urandom(10), "big")
        for _ in range(16):
            out.append(alphabet[rand & 31])
            rand >>= 5
        return "".join(reversed(out))

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(float(s))
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, latency_ms, meta=None):
        rows = _load("service_metadata.json")
        ts = _now_iso()
        rows.append(
            {
                "id": _ulid(),
                "kind": "SERVICE_STATUS",
                "chembl_version": None,
                "release_date": None,
                "service_name": "ChEMBL Server",
                "service_status": "ok" if status < 400 else "degraded",
                "message": json.dumps(
                    {
                        "event": "request",
                        "endpoint": endpoint,
                        "status": status,
                        "latency_ms": latency_ms,
                        "timestamp": ts,
                        "meta": meta or {},
                    },
                    ensure_ascii=False,
                ),
                "cache_key": None,
                "cache_payload": None,
                "expires_at": None,
                "status": "active",
                "created_at": ts,
                "updated_at": ts,
            }
        )
        _save("service_metadata.json", rows)

    def _enforce_quota(endpoint):
        rows = _load("service_metadata.json")
        now = datetime.datetime.utcnow()
        day_ago = now - datetime.timedelta(days=1)
        cnt = 0
        for r in rows:
            if r.get("kind") != "SERVICE_STATUS":
                continue
            msg = r.get("message")
            if not isinstance(msg, str):
                continue
            try:
                j = json.loads(msg)
            except Exception:
                continue
            if j.get("event") != "request" or j.get("endpoint") != endpoint:
                continue
            dt = _parse_dt(j.get("timestamp"))
            if dt and dt >= day_ago:
                cnt += 1
        if cnt >= 500:
            return _err("QUOTA_EXCEEDED", "Daily utility compute quota exceeded.", limit=500, window="24h")
        return None

    t0 = time.time()

    if not isinstance(smiles, str) or not smiles.strip():
        latency = int((time.time() - t0) * 1000)
        _log("example_is3D", 400, latency, {"error": "missing_smiles"})
        return _err("VALIDATION_ERROR", "`smiles` is required and must be a non-empty string.")
    s = smiles.strip()

    # Minimal SMILES parse validation: allowed chars and balanced parentheses/brackets.
    if any(ord(ch) < 32 for ch in s):
        latency = int((time.time() - t0) * 1000)
        _log("example_is3D", 400, latency, {"error": "control_chars"})
        return _err("VALIDATION_ERROR", "`smiles` contains invalid control characters.")
    # Balanced () check
    bal = 0
    for ch in s:
        if ch == "(":
            bal += 1
        elif ch == ")":
            bal -= 1
            if bal < 0:
                break
    if bal != 0:
        latency = int((time.time() - t0) * 1000)
        _log("example_is3D", 400, latency, {"error": "unbalanced_parentheses"})
        return _err("VALIDATION_ERROR", "`smiles` is not parseable (unbalanced parentheses).")
    # Brackets basic check
    if s.count("[") != s.count("]"):
        latency = int((time.time() - t0) * 1000)
        _log("example_is3D", 400, latency, {"error": "unbalanced_brackets"})
        return _err("VALIDATION_ERROR", "`smiles` is not parseable (unbalanced brackets).")
    # Must contain at least one atom-like token
    if not re.search(r"(\[.*?\]|Br|Cl|Si|Na|Ca|Li|Mg|Al|Zn|Fe|Cu|Mn|Se|B|C|N|O|P|S|F|I|c|n|o|s|p)", s):
        latency = int((time.time() - t0) * 1000)
        _log("example_is3D", 400, latency, {"error": "no_atoms"})
        return _err("VALIDATION_ERROR", "`smiles` is not parseable (no atom tokens found).")

    qerr = _enforce_quota("example_is3D")
    if qerr:
        latency = int((time.time() - t0) * 1000)
        _log("example_is3D", 429, latency, {"error": "quota"})
        return qerr

    # Heuristic 3D detection: presence of stereochemical/3D markers.
    # '@' indicates chirality; '\/' indicates cis/trans; also wedge/hash not in SMILES. Use these.
    try:
        is3d = ("@" in s) or ("\\" in s) or ("/" in s)
    except Exception:
        latency = int((time.time() - t0) * 1000)
        _log("example_is3D", 500, latency, {"error": "compute_failure"})
        return _err("INTERNAL_ERROR", "3D computation failed.")

    latency = int((time.time() - t0) * 1000)
    _log("example_is3D", 200, latency, {})
    return {"is_3d": bool(is3d)}

