    if qerr:
        latency = int((time.time() - t0) * 1000)
        _log("example_removeHs", 429, latency, {"error": "quota"})
        return qerr

    # "Canonicalization" surrogate: normalize whitespace only (real service would canonicalize via chemistry lib)
    canonical_smiles = re.sub(r"\s+", "", s)
    if not (1 <= len(canonical_smiles) <= 20000):
        latency = int((time.time() - t0) * 1000)
        _log("example_removeHs", 400, latency, {"error": "length"})
        return _err("VALIDATION_ERROR", "Canonical SMILES length must be between 1 and 20000 characters.")

    # Check SMILES_CACHE first
    key = canonical_smiles
    service_metadata = _load("service_metadata.json")
    now_iso = _now_iso()
    now_dt = datetime.datetime.utcnow()

    cache_row = None
    for r in service_metadata:
        if r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == key:
            cache_row = r
            break
    if cache_row:
        exp = _parse_dt(cache_row.get("expires_at"))
        if cache_row.get("status") == "active" and exp and exp > now_dt:
            payload = cache_row.get("cache_payload") if isinstance(cache_row.get("cache_payload"), dict) else {}
            out = payload.get("smiles_no_h")
            if isinstance(out, str) and out:
                latency = int((time.time() - t0) * 1000)
                _log("example_removeHs", 200, latency, {"cache": "service_metadata"})
                return {"canonical_smiles": canonical_smiles, "smiles_no_h": out, "cached": True}
        if exp and exp <= now_dt and cache_row.get("status") == "active":
            cache_row["status"] = "expired"
            cache_row["updated_at"] = now_iso
            _save("service_metadata.json", service_metadata)

    # Compute "remove Hs" offline heuristic:
    # - Remove bracketed explicit H counts like [nH], [CH3], [NH+]
    # - Remove standalone 'H' atoms (rare) when not part of 'Cl/Br/...' token.
    try:
        out = canonical_smiles

        # Replace [nH] -> [n], [NH] -> [N], [CH3] -> [C], keeping charge/isotope if present
        def _strip_h_in_bracket(m):
            inner = m.group(1)
            # remove occurrences of H optionally followed by digits, but keep 'Hg' etc not possible in bracket token; still safe
            inner2 = re.sub(r"H[0-9]*", "", inner)
            inner2 = re.sub(r"\s+", "", inner2)
            return "[" + inner2 + "]"

        out = re.sub(r"\[([^\]]+)\]", _strip_h_in_bracket, out)

        # Remove explicit hydrogens as separate atoms: "(H)" or "-H" like patterns.
        out = re.sub(r"\(H\)", "", out)
        # Remove remaining 'H' not preceded by 'C'/'B' etc? Keep 'He' doesn't exist in SMILES here.
        # Conservative: remove 'H' only when it's a standalone token (not followed/preceded by lowercase letter).
        out = re.sub(r"(?<![A-Za-z])H(?![a-z])", "", out)

        out = re.sub(r"\s+", "", out)
        if not out:
            raise ValueError("empty_result")
    except Exception:
        latency = int((time.time() - t0) * 1000)
        _log("example_removeHs", 500, latency, {"error": "standardization_failure"})
        return _err("INTERNAL_ERROR", "Hydrogen removal/standardization failed.")

    # Upsert cache row
    expires_iso = (datetime.datetime.utcnow() + datetime.timedelta(days=7)).replace(microsecond=0).isoformat() + "Z"
    if cache_row and cache_row.get("kind") == "SMILES_CACHE" and cache_row.get("cache_key") == key:
        cache_row["cache_payload"] = dict(cache_row.get("cache_payload") or {})
        cache_row["cache_payload"]["smiles_no_h"] = out
        cache_row["expires_at"] = expires_iso
        cache_row["status"] = "active"
        cache_row["updated_at"] = now_iso
    else:
        service_metadata.append(
            {
                "id": _ulid(),
                "kind": "SMILES_CACHE",
                "chembl_version": None,
                "release_date": None,
                "service_name": None,
                "service_status": None,
                "message": None,
                "cache_key": key,
                "cache_payload": {"smiles_no_h": out},
                "expires_at": expires_iso,
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso,
            }
        )
    _save("service_metadata.json", service_metadata)

    latency = int((time.time() - t0) * 1000)
    _log("example_removeHs", 200, latency, {"cache": "miss_write"})
    return {"canonical_smiles": canonical_smiles, "smiles_no_h": out, "cached": False}

