    endpoint = "example_smiles2inchi"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- minimal observable dynamics: request log + rate limiting via service_metadata SMILES_CACHE payload ---
    def _get_or_make_status_row(md):
        row = None
        for r in md:
            if r.get("kind") == "SERVICE_STATUS" and r.get("status") == "active":
                row = r
                break
        if row is None:
            row = {
                "id": _ulid(),
                "kind": "SERVICE_STATUS",
                "chembl_version": None,
