            row["cache_payload"]["rate_limit"] = {"window_seconds": 60, "max_requests": 120}
        return row

    def _record_and_maybe_limit(md, status_code, latency_ms, precheck_only=False):
        # precheck_only: still records with status_code "rate_limited" etc.
        status_row = _get_or_make_status_row(md)
        rl = status_row["cache_payload"].get("rate_limit") or {}
        window_seconds = rl.get("window_seconds", 60)
        max_requests = rl.get("max_requests", 120)
        try:
            window_seconds = int(window_seconds)
            max_requests = int(max_requests)
        except Exception:
            window_seconds, max_requests = 60, 120
        if window_seconds <= 0:
            window_seconds = 60
        if max_requests <= 0:
            max_requests = 120

        log = status_row["cache_payload"]["request_log"]
        # prune old
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_seconds)
        kept = []
        for e in log:
            ts = e.get("ts")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                kept.append(e)
        log[:] = kept

        # enforce
        if len(log) >= max_requests and status_code == "ok":
            # cannot accept; record rate limited
            status_code = "rate_limited"

        log.append({
            "id": _ulid(),
            "endpoint": endpoint,
            "ts": now,
            "status": status_code,
            "latency_ms": int(latency_ms),
        })
        status_row["updated_at"] = now
        _save("service_metadata.json", md)
        return status_code

    def _ulid():
        # 26 char Crockford-ish base32 from time+random
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        r = int.from_bytes(os.urandom(10), "big")
        v = (ms << 80) | r
        out = []
        for _ in range(26):
            out.append(alphabet[v & 31])
            v >>= 5
        return "".join(reversed(out))

