        return _err("VALIDATION_ERROR", "`smiles` must be a non-empty string.")
    s = smiles.strip()
    if not s:
        _record_and_maybe_limit(md, "validation_error", (time.time() - start) * 1000)
        return _err("VALIDATION_ERROR", "`smiles` must be a non-empty string.")

    # very lightweight "parse" validation (offline): allowed chars and balanced brackets/parentheses
    allowed = re.compile(r"^[A-Za-z0-9@+\-\[\]\(\)=#$\\/%.:*,;!?~^\s]+$")
    if not allowed.match(s):
