    # rate limit precheck/record
    st = _record_and_maybe_limit(md, "ok", (time.time() - start) * 1000, precheck_only=True)
    if st == "rate_limited":
        return _err("RATE_LIMIT", "RATE_LIMIT_EXCEEDED")

    # --- normalize to canonical_smiles (deterministic approximation) ---
    canonical = re.sub(r"\s+", "", s)

    # try to return cached InChI from compound_structures if exists for canonical_smiles
    cs = _load("compound_structures.json")
    for r in cs:
        if r.get("status") == "active" and r.get("canonical_smiles") == canonical and isinstance(r.get("inchi"), str) and r.get("inchi"):
            # record success
            _record_and_maybe_limit(_load("service_metadata.json"), "ok", (time.time() - start) * 1000)
            return {"inchi": r["inchi"]}

    # else use SMILES_CACHE
    md = _load("service_metadata.json")
    cache_row = None
    for r in md:
        if r.get("kind") == "SMILES_CACHE" and r.get("status") == "active" and r.get("cache_key") == canonical:
            cache_row = r
            break

    def _is_unexpired(row):
        exp = row.get("expires_at")
        if not exp:
            return False
        try:
            dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00"))
        except Exception:
            return False
        return dt > datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    if cache_row and _is_unexpired(cache_row):
        payload = cache_row.get("cache_payload") if isinstance(cache_row.get("cache_payload"), dict) else {}
        inchi = payload.get("inchi")
        if isinstance(inchi, str) and inchi:
            _record_and_maybe_limit(_load("service_metadata.json"), "ok", (time.time() - start) * 1000)
            return {"inchi": inchi}

    # compute InChI deterministically (offline placeholder that is stable)
    try:
        h = hashlib.sha256(canonical.encode("utf-8")).digest()
        token = base64.b32encode(h).decode("ascii").rstrip("=")
        inchi = "InChI=1S/" + token
    except Exception:
        _record_and_maybe_limit(_load("service_metadata.json"), "internal_error", (time.time() - start) * 1000)
        return _err("INTERNAL_ERROR", "Conversion failed unexpectedly during processing.")

    # upsert cache
    md = _load("service_metadata.json")
    expires = (datetime.datetime.utcnow() + datetime.timedelta(days=7)).replace(microsecond=0).isoformat() + "Z"
    updated = False
    for r in md:
        if r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == canonical:
            # update existing
            if r.get("status") != "active":
                r["status"] = "active"
            if not isinstance(r.get("cache_payload"), dict) or r.get("cache_payload") is None:
                r["cache_payload"] = {}
            r["cache_payload"]["inchi"] = inchi
            r["expires_at"] = expires
            r["updated_at"] = now
            updated = True
            break
    if not updated:
        md.append({
            "id": _ulid(),
            "kind": "SMILES_CACHE",
            "chembl_version": None,
            "release_date": None,
            "service_name": None,
            "service_status": None,
            "message": None,
            "cache_key": canonical,
            "cache_payload": {"inchi": inchi},
            "expires_at": expires,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        })
    _save("service_metadata.json", md)

    _record_and_maybe_limit(_load("service_metadata.json"), "ok", (time.time() - start) * 1000)
    return {"inchi": inchi}

