def example_standardize(smiles, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "example_standardize"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        r = int.from_bytes(os.urandom(10), "big")
        v = (ms << 80) | r
        out = []
        for _ in range(26):
            out.append(alphabet[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _get_or_make_status_row(md):
        row = None
        for r in md:
            if r.get("kind") == "SERVICE_STATUS" and r.get("status") == "active":
                row = r
                break
        if row is None:
            row = {
                "id": _ulid(),
                "kind": "SERVICE_STATUS",
                "chembl_version": None,
                "release_date": None,
                "service_name": "ChEMBL Server",
                "service_status": "ok",
                "message": "Auto-initialized service status",
                "cache_key": None,
                "cache_payload": {},
                "expires_at": None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            md.append(row)
        if not isinstance(row.get("cache_payload"), dict) or row.get("cache_payload") is None:
            row["cache_payload"] = {}
        if "request_log" not in row["cache_payload"] or not isinstance(row["cache_payload"].get("request_log"), list):
            row["cache_payload"]["request_log"] = []
        if "rate_limit" not in row["cache_payload"] or not isinstance(row["cache_payload"].get("rate_limit"), dict):
            row["cache_payload"]["rate_limit"] = {"window_seconds": 60, "max_requests": 120}
        return row

    def _record_and_maybe_limit(md, status_code, latency_ms):
        status_row = _get_or_make_status_row(md)
        rl = status_row["cache_payload"].get("rate_limit") or {}
        try:
            window_seconds = int(rl.get("window_seconds", 60))
            max_requests = int(rl.get("max_requests", 120))
        except Exception:
            window_seconds, max_requests = 60, 120
        if window_seconds <= 0:
            window_seconds = 60
        if max_requests <= 0:
            max_requests = 120

        log = status_row["cache_payload"]["request_log"]
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_seconds)
        kept = []
        for e in log:
            ts = e.get("ts")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                kept.append(e)
        log[:] = kept

        if len(log) >= max_requests and status_code == "ok":
            status_code = "rate_limited"

        log.append({
            "id": _ulid(),
            "endpoint": endpoint,
            "ts": now,
            "status": status_code,
            "latency_ms": int(latency_ms),
        })
        status_row["updated_at"] = now
        _save("service_metadata.json", md)
        return status_code

    md = _load("service_metadata.json")

    if smiles is None or not isinstance(smiles, str):
        _record_and_maybe_limit(md, "validation_error", (time.time() - start) * 1000)
        return _err("VALIDATION_ERROR", "`smiles` must be a non-empty string.")
    s = smiles.strip()
    if not s:
        _record_and_maybe_limit(md, "validation_error", (time.time() - start) * 1000)
        return _err("VALIDATION_ERROR", "`smiles` must be a non-empty string.")

    allowed = re.compile(r"^[A-Za-z0-9@+\-\[\]\(\)=#$\\/%.:*,;!?~^\s]+$")
    if not allowed.match(s):
        _record_and_maybe_limit(md, "validation_error", (time.time() - start) * 1000)
        return _err("VALIDATION_ERROR", "`smiles` contains invalid characters and cannot be parsed.")
    if s.count("(") != s.count(")") or s.count("[") != s.count("]"):
        _record_and_maybe_limit(md, "validation_error", (time.time() - start) * 1000)
        return _err("VALIDATION_ERROR", "`smiles` appears malformed (unbalanced parentheses/brackets).")

    st = _record_and_maybe_limit(_load("service_metadata.json"), "ok", (time.time() - start) * 1000)
    if st == "rate_limited":
        return _err("RATE_LIMIT", "RATE_LIMIT_EXCEEDED")

    # standardization (offline approximation): remove whitespace, collapse consecutive '.', uppercase aromatic 'se'/'as'? keep as-is,
    # also normalize backslashes to forward slashes for determinism.
    try:
        standardized = re.sub(r"\s+", "", s)
        standardized = re.sub(r"\.+", ".", standardized).strip(".")
        standardized = standardized.replace("\\", "/")
        if not standardized:
            raise ValueError("empty after standardization")
    except Exception:
        _record_and_maybe_limit(_load("service_metadata.json"), "internal_error", (time.time() - start) * 1000)
        return _err("INTERNAL_ERROR", "Standardization failed unexpectedly during processing.")

    # Upsert cache: store standardized_smiles under SMILES_CACHE for canonical key
    canonical = standardized  # treat standardized as canonical for this offline service
    md = _load("service_metadata.json")
    expires = (datetime.datetime.utcnow() + datetime.timedelta(days=7)).replace(microsecond=0).isoformat() + "Z"
    updated = False
    for r in md:
        if r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == canonical:
            if r.get("status") != "active":
                r["status"] = "active"
            if not isinstance(r.get("cache_payload"), dict) or r.get("cache_payload") is None:
                r["cache_payload"] = {}
            r["cache_payload"]["standardized_smiles"] = standardized
            r["expires_at"] = expires
            r["updated_at"] = now
            updated = True
            break
    if not updated:
        md.append({
            "id": _ulid(),
            "kind": "SMILES_CACHE",
            "chembl_version": None,
            "release_date": None,
            "service_name": None,
            "service_status": None,
            "message": None,
            "cache_key": canonical,
            "cache_payload": {"standardized_smiles": standardized},
            "expires_at": expires,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        })
    _save("service_metadata.json", md)

    _record_and_maybe_limit(_load("service_metadata.json"), "ok", (time.time() - start) * 1000)
    return {"standardized_smiles": standardized}

def example_status(**_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")

    def _load(n):
