                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if not v:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _record_call(endpoint, status, latency_ms, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"r_{int(time.time() * 1000)}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits(endpoint):
        # Prefer explicit policy file if present
        policy = {}
        pol = _load("rate_limit_policy.json")
        if isinstance(pol, dict):
            policy = pol
        elif isinstance(pol, list) and pol:
            # allow single-row list
            if isinstance(pol[0], dict):
                policy = pol[0]

        # Defaults if not provided by store
        window_seconds = int(policy.get("window_seconds", 60))
        max_requests_per_window = policy.get("max_requests_per_window", 300)
        max_requests_per_day = policy.get("max_requests_per_day", 20000)

        if not isinstance(window_seconds, int) or window_seconds <= 0:
            window_seconds = 60
        if not isinstance(max_requests_per_window, int) or max_requests_per_window <= 0:
            max_requests_per_window = 300
        if not isinstance(max_requests_per_day, int) or max_requests_per_day <= 0:
            max_requests_per_day = 20000

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)
        win_start = now - datetime.timedelta(seconds=window_seconds)
        day_start = now - datetime.timedelta(days=1)

        in_window = 0
        in_day = 0
        for r in logs:
            ts = _parse_dt(r.get("ts"))
            if not ts:
                continue
            if ts >= win_start:
                in_window += 1
            if ts >= day_start:
                in_day += 1

        if in_window >= max_requests_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=max_requests_per_window, window_seconds=window_seconds)
        if in_day >= max_requests_per_day:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota=max_requests_per_day, window="24h")
        return None

    t0 = time.time()
    endpoint = "example_status"

    limit_err = _check_limits(endpoint)
    if limit_err:
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=limit_err["error"]["code"])
        return limit_err

    # Retrieve active SERVICE_STATUS row
    meta = _load("service_metadata.json")
    if not isinstance(meta, list):
        err = _err("NOT_FOUND", "Service metadata store is unavailable or invalid.")
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=err["error"]["code"])
        return err

    rows = [
        r for r in meta
        if isinstance(r, dict)
        and r.get("kind") == "SERVICE_STATUS"
        and r.get("status") == "active"
    ]
    if not rows:
        err = _err("NOT_FOUND", "Service status metadata not found.")
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=err["error"]["code"])
        return err

    # unique(kind) where kind='SERVICE_STATUS' => pick the single row if multiple
    row = rows[0]
    out = {
        "service_name": row.get("service_name"),
        "service_status": row.get("service_status"),
        "message": row.get("message"),
        "updated_at": row.get("updated_at"),
    }

    _record_call(endpoint, "ok", (time.time() - t0) * 1000)
    return {"status": out}

def example_structuralAlerts(smiles, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if not v:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _record_call(endpoint, status, latency_ms, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"r_{int(time.time() * 1000)}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits(endpoint):
        policy = {}
        pol = _load("rate_limit_policy.json")
        if isinstance(pol, dict):
            policy = pol
        elif isinstance(pol, list) and pol and isinstance(pol[0], dict):
            policy = pol[0]

        window_seconds = int(policy.get("window_seconds", 60))
        max_requests_per_window = policy.get("max_requests_per_window", 300)
        max_requests_per_day = policy.get("max_requests_per_day", 20000)

        if not isinstance(window_seconds, int) or window_seconds <= 0:
            window_seconds = 60
        if not isinstance(max_requests_per_window, int) or max_requests_per_window <= 0:
            max_requests_per_window = 300
        if not isinstance(max_requests_per_day, int) or max_requests_per_day <= 0:
            max_requests_per_day = 20000

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)
        win_start = now - datetime.timedelta(seconds=window_seconds)
        day_start = now - datetime.timedelta(days=1)

        in_window = 0
        in_day = 0
        for r in logs:
            ts = _parse_dt(r.get("ts"))
            if not ts:
                continue
            if ts >= win_start:
                in_window += 1
            if ts >= day_start:
                in_day += 1

        if in_window >= max_requests_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=max_requests_per_window, window_seconds=window_seconds)
        if in_day >= max_requests_per_day:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota=max_requests_per_day, window="24h")
        return None

    def _canonicalize_smiles(s):
        # Minimal deterministic normalization (offline; no chemistry toolkit).
        # Validation: non-empty, reasonable characters, balanced brackets/parentheses.
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", "smiles must be a string.")
        t = s.strip()
        if not t:
            return None, _err("VALIDATION_ERROR", "smiles is required.")
        if len(t) > 20000:
            return None, _err("VALIDATION_ERROR", "smiles is too long.", max_length=20000)
        # Allowed characters (broadly SMILES-like)
        if re.search(r"[^A-Za-z0-9@\+\-\=\#\:\.\(\)\[\]\\/%%\*\,\$\{\}]", t):
            return None, _err("VALIDATION_ERROR", "smiles contains invalid characters.")
        # Balance parentheses and brackets
        bal = 0
        for ch in t:
            if ch == "(":
                bal += 1
            elif ch == ")":
                bal -= 1
                if bal < 0:
                    return None, _err("VALIDATION_ERROR", "smiles has unbalanced parentheses.")
        if bal != 0:
            return None, _err("VALIDATION_ERROR", "smiles has unbalanced parentheses.")
        bbal = 0
        for ch in t:
            if ch == "[":
                bbal += 1
            elif ch == "]":
                bbal -= 1
                if bbal < 0:
                    return None, _err("VALIDATION_ERROR", "smiles has unbalanced brackets.")
        if bbal != 0:
            return None, _err("VALIDATION_ERROR", "smiles has unbalanced brackets.")
        # Canonical key: collapse whitespace, uppercase aromatic not attempted; stable "canonical" proxy
        t = re.sub(r"\s+", "", t)
        return t, None

    def _is_unexpired(row):
        if not isinstance(row, dict):
            return False
        if row.get("kind") != "SMILES_CACHE":
            return False
        if row.get("status") != "active":
            return False
        exp = _parse_dt(row.get("expires_at"))
        if not exp:
            return False
        now = datetime.datetime.now(datetime.timezone.utc)
        return exp > now

    def _compute_alerts(canon):
        # Simple structural alert heuristics as deterministic pattern matches.
        alerts = []

        def add(code, name, matched, severity="moderate"):
            alerts.append({"code": code, "name": name, "matched": matched, "severity": severity})

        s = canon

        # Nitro
        if re.search(r"N(\(=O\)=O|(\+)\(=O\)\[O-\])", s):
            add("ALERT_NITRO", "Nitro group", "N(=O)=O", severity="moderate")

        # Azide
        if "N=[N+]=[N-]" in s or "N#N#N" in s or re.search(r"N=N=N", s):
            add("ALERT_AZIDE", "Azide-like motif", "N=N=N", severity="high")

        # Epoxide (very rough)
        if re.search(r"C1OC1", s) or re.search(r"O1CC1", s):
            add("ALERT_EPOXIDE", "Epoxide ring (heuristic)", "C1OC1", severity="moderate")

        # Michael acceptor (alpha,beta-unsat carbonyl; heuristic)
        if re.search(r"C=CC(=O)", s) or re.search(r"C=CC\(=O\)", s) or re.search(r"C=CC=O", s):
            add("ALERT_MICHAEL_ACCEPTOR", "Michael acceptor (heuristic)", "C=CC(=O)", severity="moderate")

        # Aldehyde
        if re.search(r"C=O", s) and re.search(r"[CH]\=O|C=O", s):
            # keep conservative: only flag explicit "C=O" with terminal-ish pattern is hard; use heuristic if contains "C=O" and not "C(=O)O"
            if not re.search(r"C\(=O\)O", s):
                add("ALERT_ALDEHYDE_OR_CARBONYL", "Reactive carbonyl (heuristic)", "C=O", severity="low")

        # Aniline (aryl amine; heuristic: "c...N")
        if re.search(r"c[nc]*N", s) or re.search(r"c1.*N.*c1", s):
            add("ALERT_ARYL_AMINE", "Aryl amine (heuristic)", "aryl-N", severity="moderate")

        # Halogenated (broad)
        if re.search(r"Cl|Br|I|F", s):
            add("ALERT_HALOGEN", "Contains halogen", "X", severity="low")

        return alerts

    t0 = time.time()
    endpoint = "example_structuralAlerts"

    limit_err = _check_limits(endpoint)
    if limit_err:
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=limit_err["error"]["code"])
        return limit_err

    canon, verr = _canonicalize_smiles(smiles)
    if verr:
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=verr["error"]["code"])
        return verr

    meta = _load("service_metadata.json")
    if not isinstance(meta, list):
        meta = []

    # Try cache first
    cache_row = None
    for r in meta:
        if isinstance(r, dict) and r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == canon:
            if _is_unexpired(r) and isinstance(r.get("cache_payload"), dict) and "structural_alerts" in r["cache_payload"]:
                cache_row = r
                break

    if cache_row is not None:
        payload = cache_row.get("cache_payload") or {}
        alerts = payload.get("structural_alerts")
        if not isinstance(alerts, list):
            alerts = []
        _record_call(endpoint, "ok", (time.time() - t0) * 1000, detail="cache_hit")
        return {"smiles": smiles, "canonical_smiles": canon, "alerts": alerts, "cached": True}

    # Compute and upsert cache
    alerts = _compute_alerts(canon)

    now = datetime.datetime.now(datetime.timezone.utc)
    expires = now + datetime.timedelta(days=30)

    # Upsert unique(kind, cache_key)
    found_idx = None
    for i, r in enumerate(meta):
        if isinstance(r, dict) and r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == canon:
            found_idx = i
            break

    if found_idx is None:
        new_row = {
            "id": f"m_{int(time.time() * 1000)}_{len(meta)+1}",
            "kind": "SMILES_CACHE",
            "cache_key": canon,
            "cache_payload": {"structural_alerts": alerts},
            "expires_at": expires.isoformat(),
            "status": "active",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        meta.append(new_row)
    else:
        r = meta[found_idx]
        if not isinstance(r, dict):
            r = {}
            meta[found_idx] = r
        r["kind"] = "SMILES_CACHE"
        r["cache_key"] = canon
        payload = r.get("cache_payload")
        if not isinstance(payload, dict):
            payload = {}
        payload["structural_alerts"] = alerts
        r["cache_payload"] = payload
        r["expires_at"] = expires.isoformat()
        r["status"] = "active"
        if not r.get("created_at"):
            r["created_at"] = _now_iso()
        r["updated_at"] = _now_iso()

    _save("service_metadata.json", meta)
    _record_call(endpoint, "ok", (time.time() - t0) * 1000, detail="computed")
    return {"smiles": smiles, "canonical_smiles": canon, "alerts": alerts, "cached": False}

