                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _record_call(endpoint, status_s, latency_ms, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"r_{int(time.time() * 1000)}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int(latency_ms),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits(endpoint):
        policy = {}
        pol = _load("rate_limit_policy.json")
        if isinstance(pol, dict):
            policy = pol
        elif isinstance(pol, list) and pol and isinstance(pol[0], dict):
            policy = pol[0]

        window_seconds = int(policy.get("window_seconds", 60))
        max_requests_per_window = policy.get("max_requests_per_window", 300)
        max_requests_per_day = policy.get("max_requests_per_day", 20000)

        if not isinstance(window_seconds, int) or window_seconds <= 0:
            window_seconds = 60
        if not isinstance(max_requests_per_window, int) or max_requests_per_window <= 0:
            max_requests_per_window = 300
        if not isinstance(max_requests_per_day, int) or max_requests_per_day <= 0:
            max_requests_per_day = 20000

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)
        win_start = now - datetime.timedelta(seconds=window_seconds)
        day_start = now - datetime.timedelta(days=1)

        in_window = 0
        in_day = 0
        for r in logs:
            ts = _parse_dt(r.get("ts"))
            if not ts:
                continue
            if ts >= win_start:
                in_window += 1
            if ts >= day_start:
                in_day += 1

        if in_window >= max_requests_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=max_requests_per_window, window_seconds=window_seconds)
        if in_day >= max_requests_per_day:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota=max_requests_per_day, window="24h")
        return None

    t0 = time.time()
    endpoint = "example_entity_search"

    limit_err = _check_limits(endpoint)
    if limit_err:
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=limit_err["error"]["code"])
        return limit_err

    allowed_types = {
        "MOLECULE": "MOLECULE",
        "TARGET": "TARGET",
        "ASSAY": "ASSAY",
        "ACTIVITY": "ACTIVITY",
        "DOCUMENT": "DOCUMENT",
        "CELL_LINE": "CELL_LINE",
        "TISSUE": "TISSUE",
        "SOURCE": "SOURCE",
        "MECHANISM": "MECHANISM",
        "DRUG_INDICATION": "DRUG_INDICATION",
        "DRUG_WARNING": "DRUG_WARNING",
        "GO_SLIM": "GO_SLIM",
        "ATC_CLASS": "ATC_CLASS",
        "BIOCOMPONENT": "TARGET_COMPONENT",  # tool alias
        "RELATIONSHIP": "TARGET_RELATION",   # tool alias
        "BIOTHERAPEUTIC": "BIOTHERAPEUTIC",
        "PROTEIN_CLASSIFICATION": "PROTEIN_CLASS",  # tool alias
        "XREF_SOURCE": "XREF_SOURCE",
        "COMPOUND_RECORD": "COMPOUND_RECORD",
        "COMPOUND_STRUCTURAL_ALERT": "STRUCTURAL_ALERT",  # tool alias
    }

    if not isinstance(entity_type, str) or entity_type not in allowed_types:
        err = _err("VALIDATION_ERROR", "Unknown entity_type.", allowed=list(allowed_types.keys()))
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=err["error"]["code"])
        return err

    mapped = allowed_types[entity_type]

    if q is not None and (not isinstance(q, str) or not q.strip()):
        err = _err("VALIDATION_ERROR", "q must be a non-empty string when provided.")
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=err["error"]["code"])
        return err
    if chembl_id_prefix is not None and (not isinstance(chembl_id_prefix, str) or not chembl_id_prefix.strip()):
        err = _err("VALIDATION_ERROR", "chembl_id_prefix must be a non-empty string when provided.")
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=err["error"]["code"])
        return err

    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "deprecated", "merged"):
        err = _err("VALIDATION_ERROR", "Invalid status filter.", allowed=["active", "deprecated", "merged"])
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=err["error"]["code"])
        return err

    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        err = _err("VALIDATION_ERROR", "Invalid page; must be integer >= 1.")
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=err["error"]["code"])
        return err
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        err = _err("VALIDATION_ERROR", "Invalid page_size; must be integer in [1, 200].")
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=err["error"]["code"])
        return err

    entities = _load("chembl_entities.json")
    if not isinstance(entities, list):
        err = _err("NOT_FOUND", "Entity store is unavailable or invalid.")
        _record_call(endpoint, "error", (time.time() - t0) * 1000, detail=err["error"]["code"])
        return err

    qn = q.strip().lower() if isinstance(q, str) else None
    pn = chembl_id_prefix.strip().lower() if isinstance(chembl_id_prefix, str) else None

    results = []
    for r in entities:
        if not isinstance(r, dict):
            continue
        if r.get("entity_type") != mapped:
            continue
        if r.get("status") != status:
            continue

        chembl_id = (r.get("chembl_id") or "")
        off = (r.get("official_name") or "")
        desc = (r.get("description_text") or "")

        if pn is not None and not chembl_id.lower().startswith(pn):
            continue

        score = 0
        if qn is not None:
            cid = chembl_id.lower()
            if cid.startswith(qn):
                score += 3
            if qn in off.lower():
                score += 1
            if qn in desc.lower():
                score += 1
            if score == 0:
                continue

        updated = _parse_dt(r.get("updated_at")) or datetime.datetime.fromtimestamp(0, datetime.timezone.utc)
        results.append((score, updated, r))

    # Order by relevance then updated_at desc
    results.sort(key=lambda t: (t[0], t[1]), reverse=True)
    rows = [t[2] for t in results]

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]

    has_more = end < total
    next_page = (page + 1) if has_more else None

    _record_call(endpoint, "ok", (time.time() - t0) * 1000)
    return {
        "data": page_rows,
        "meta": {
            "entity_type": entity_type,
            "mapped_entity_type": mapped,
            "total": total,
            "page": page,
            "page_size": page_size,
            "has_more": has_more,
            "next_page": next_page,
        },
    }

