def example_compound_structure_by_chembl_id(chembl_id, include_svg=None, **_extra):
    import json, os, datetime, time, random, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "example_compound_structure_by_chembl_id"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_used=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _check_limits():
        limits = _load("service_limits.json")
        if not isinstance(limits, dict): limits = {}
        rl = limits.get("rate_limit", {"window_seconds": 60, "max_requests": 120})
        qt = limits.get("quota", {"daily_max_requests": 20000})

        window_seconds = int(rl.get("window_seconds", 60) or 60)
        max_requests = int(rl.get("max_requests", 120) or 120)
        daily_max = int(qt.get("daily_max_requests", 20000) or 20000)

        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=window_seconds)
        day_cutoff = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str): return None
            try:
                if s.endswith("Z"): s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        in_window = 0
        in_day = 0
        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if not ts: 
                continue
            if ts >= cutoff:
                in_window += 1
            if ts >= day_cutoff:
                in_day += 1

        if in_window >= max_requests:
            return _err("RATE_LIMIT", "Too many requests in a short time window.", window_seconds=window_seconds, max_requests=max_requests)
        if in_day >= daily_max:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_max_requests=daily_max)
        return None

    # Rate/quota check (log refused calls too)
    limerr = _check_limits()
    if limerr:
        _log("RATE_LIMIT" if limerr["error"]["code"] == "RATE_LIMIT" else "QUOTA_EXCEEDED", detail=limerr["error"])
        return limerr

    # Validate inputs
    if not isinstance(chembl_id, str) or not chembl_id.strip():
        _log("VALIDATION_ERROR", detail={"field": "chembl_id"})
        return _err("VALIDATION_ERROR", "chembl_id must be a non-empty string.", field="chembl_id")
    chembl_id = chembl_id.strip()

    if include_svg is None:
        include_svg = False
    if not isinstance(include_svg, bool):
        _log("VALIDATION_ERROR", detail={"field": "include_svg"})
        return _err("VALIDATION_ERROR", "include_svg must be a boolean.", field="include_svg")

    # Ambient auth: service is public; only deny if service is explicitly down
    meta = _load("service_metadata.json")
    if not isinstance(meta, list): meta = []
    svc = None
    for r in meta:
        if isinstance(r, dict) and r.get("kind") == "SERVICE_STATUS" and r.get("status") == "active":
            svc = r
            break
    if svc and svc.get("service_status") == "down":
        _log("UNAUTHORIZED", detail={"reason": "service_down"})
        return _err("UNAUTHORIZED", "Access is not permitted at this time.")

    entities = _load("chembl_entities.json")
    if not isinstance(entities, list): entities = []
    ent = None
    for e in entities:
        if isinstance(e, dict) and e.get("chembl_id") == chembl_id:
            ent = e
            break

    if not ent:
        _log("VALIDATION_ERROR", detail={"reason": "chembl_id_not_found"})
        return _err("VALIDATION_ERROR", "chembl_id is not recognized.", field="chembl_id")

    if ent.get("entity_type") != "MOLECULE":
        _log("VALIDATION_ERROR", detail={"reason": "not_molecule", "entity_type": ent.get("entity_type")})
        return _err("VALIDATION_ERROR", "chembl_id must refer to a MOLECULE entity.", field="chembl_id", entity_type=ent.get("entity_type"))

    structures = _load("compound_structures.json")
    if not isinstance(structures, list): structures = []
    srow = None
    for s in structures:
        if isinstance(s, dict) and s.get("entity_id") == ent.get("id") and s.get("status") == "active":
            srow = s
            break

    if not srow:
        _log("NOT_FOUND", detail={"reason": "no_active_structure"})
        return _err("NOT_FOUND", "No active structure exists for this molecule.", chembl_id=chembl_id)

    # Optionally include svg; may use existing svg_2d or cache by canonical_smiles
    out = dict(srow)
    if not include_svg:
        out.pop("svg_2d", None)
    else:
        if not out.get("svg_2d"):
            canonical = out.get("canonical_smiles")
            # Try cache
            cache_row = None
            for r in meta:
                if isinstance(r, dict) and r.get("kind") == "SMILES_CACHE" and r.get("status") == "active" and r.get("cache_key") == canonical:
                    # check expiry
                    exp = r.get("expires_at")
                    ok = False
                    if isinstance(exp, str):
                        try:
                            exps = exp[:-1] if exp.endswith("Z") else exp
                            ok = datetime.datetime.fromisoformat(exps) > datetime.datetime.utcnow()
                        except Exception:
                            ok = False
                    if ok:
                        cache_row = r
                    break
            svg = None
            if cache_row:
                payload = cache_row.get("cache_payload")
                if isinstance(payload, dict):
                    svg = payload.get("svg_2d")
            if svg is None and canonical:
                # Compute a deterministic placeholder SVG depiction (offline)
                h = hashlib.sha256(canonical.encode("utf-8")).digest()
                color = f"#{h[0]:02x}{h[1]:02x}{h[2]:02x}"
                label = canonical if len(canonical) <= 64 else canonical[:61] + "..."
                svg = (
                    f"<svg xmlns='http://www.w3.org/2000/svg' width='420' height='120'>"
                    f"<rect x='0' y='0' width='420' height='120' fill='{color}' opacity='0.10'/>"
                    f"<rect x='10' y='10' width='400' height='100' fill='white' stroke='{color}'/>"
                    f"<text x='20' y='55' font-family='monospace' font-size='12' fill='black'>SMILES:</text>"
                    f"<text x='20' y='75' font-family='monospace' font-size='10' fill='black'>{label}</text>"
                    f"</svg>"
                )
                # Upsert cache payload.svg_2d with a default TTL (7 days)
                ttl = 7 * 24 * 3600
                expires_at = (datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl)).replace(microsecond=0).isoformat() + "Z"
                # find existing cache row
                existing = None
                for r in meta:
                    if isinstance(r, dict) and r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == canonical:
                        existing = r
                        break
                nowiso = _now_iso()
                if existing:
                    if not isinstance(existing.get("cache_payload"), dict):
                        existing["cache_payload"] = {}
                    existing["cache_payload"]["svg_2d"] = svg
                    existing["expires_at"] = expires_at
                    existing["status"] = "active"
                    existing["updated_at"] = nowiso
                else:
                    meta.append({
                        "id": f"md_{int(time.time()*1000)}_{random.randint(1000,9999)}",
                        "kind": "SMILES_CACHE",
                        "chembl_version": None,
                        "release_date": None,
                        "service_name": None,
                        "service_status": None,
                        "message": None,
                        "cache_key": canonical,
                        "cache_payload": {"svg_2d": svg},
                        "expires_at": expires_at,
                        "status": "active",
                        "created_at": nowiso,
                        "updated_at": nowiso
                    })
                _save("service_metadata.json", meta)

            out["svg_2d"] = svg

    resp = {
        "chembl_id": chembl_id,
        "entity_id": ent.get("id"),
        "structure": out
    }
    _log("OK")
    return resp

