            "endpoint": endpoint,
            "credential_used": None,
            "status": "RATE_LIMIT",
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        usage["total_calls"] = int(usage.get("total_calls", 0) or 0) + 1
        by_ep[endpoint] = int(by_ep.get(endpoint, 0) or 0) + 1
        service_row["updated_at"] = _now_iso()
        _save("service_metadata.json", meta)
        return _err("RATE_LIMIT", "Too many requests in the current time window.")
    if in_day >= daily_max_requests:
        req_log.append({
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": endpoint,
            "credential_used": None,
            "status": "QUOTA_EXCEEDED",
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        usage["total_calls"] = int(usage.get("total_calls", 0) or 0) + 1
        by_ep[endpoint] = int(by_ep.get(endpoint, 0) or 0) + 1
        service_row["updated_at"] = _now_iso()
        _save("service_metadata.json", meta)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    # Validate pagination
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.", page=page)
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.", page_size=page_size)

    # Validate status enum
    if status is None:
        status = "active"
    if status not in ("active", "retracted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, retracted.", status=status)

    # Validate numeric bounds
    if min_pchembl is not None and not isinstance(min_pchembl, (int, float)):
        return _err("VALIDATION_ERROR", "min_pchembl must be a number.", min_pchembl=min_pchembl)
    if max_pchembl is not None and not isinstance(max_pchembl, (int, float)):
        return _err("VALIDATION_ERROR", "max_pchembl must be a number.", max_pchembl=max_pchembl)
    if min_pchembl is not None and max_pchembl is not None and min_pchembl > max_pchembl:
        return _err("VALIDATION_ERROR", "min_pchembl cannot be greater than max_pchembl.", min_pchembl=min_pchembl, max_pchembl=max_pchembl)

    # Resolve optional chembl_id filters
    entities = _load("chembl_entities.json")
    if not isinstance(entities, list):
        entities = []
    def _resolve(chembl_id, required_type):
        if chembl_id is None:
            return None
        if not isinstance(chembl_id, str) or not chembl_id.strip():
            raise ValueError(f"{required_type}_chembl_id must be a non-empty string")
        cid = chembl_id.strip()
        for e in entities:
            if isinstance(e, dict) and e.get("chembl_id") == cid and e.get("entity_type") == required_type:
                return e.get("id")
        return "__NO_MATCH__"

    try:
        assay_id = _resolve(assay_chembl_id, "ASSAY")
        molecule_id = _resolve(molecule_chembl_id, "MOLECULE")
        target_id = _resolve(target_chembl_id, "TARGET")
    except ValueError as ve:
        return _err("VALIDATION_ERROR", str(ve))

    # If a filter was provided but can't be resolved, return empty set (read => no error)
    if assay_id == "__NO_MATCH__" or molecule_id == "__NO_MATCH__" or target_id == "__NO_MATCH__":
        req_log.append({
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": endpoint,
            "credential_used": None,
            "status": "OK",
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        usage["total_calls"] = int(usage.get("total_calls", 0) or 0) + 1
        by_ep[endpoint] = int(by_ep.get(endpoint, 0) or 0) + 1
        service_row["updated_at"] = _now_iso()
        _save("service_metadata.json", meta)
        return {
            "page": page,
            "page_size": page_size,
            "total": 0,
            "has_more": False,
            "results": [],
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }

    acts = _load("activities.json")
    if not isinstance(acts, list):
        acts = []

    filtered = []
    for a in acts:
        if not isinstance(a, dict):
            continue
        if a.get("status") != status:
            continue
        if assay_id is not None and a.get("assay_entity_id") != assay_id:
            continue
        if molecule_id is not None and a.get("molecule_entity_id") != molecule_id:
            continue
        if target_id is not None and a.get("target_entity_id") != target_id:
            continue
        if standard_type is not None:
            if not isinstance(standard_type, str) or not standard_type.strip():
                return _err("VALIDATION_ERROR", "standard_type must be a non-empty string when provided.", standard_type=standard_type)
            if (a.get("standard_type") or "") != standard_type:
                continue
        if standard_units is not None:
            if not isinstance(standard_units, str) or not standard_units.strip():
                return _err("VALIDATION_ERROR", "standard_units must be a non-empty string when provided.", standard_units=standard_units)
            if (a.get("standard_units") or "") != standard_units:
                continue
        pv = a.get("pchembl_value")
        if min_pchembl is not None:
            if pv is None or not isinstance(pv, (int, float)) or pv < float(min_pchembl):
                continue
        if max_pchembl is not None:
            if pv is None or not isinstance(pv, (int, float)) or pv > float(max_pchembl):
                continue
        filtered.append(dict(a))

    total = len(filtered)
    start = (page - 1) * page_size
    end = start + page_size
    results = filtered[start:end]
    has_more = end < total

    req_log.append({
        "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
        "endpoint": endpoint,
        "credential_used": None,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "timestamp": _now_iso(),
    })
    usage["total_calls"] = int(usage.get("total_calls", 0) or 0) + 1
    by_ep[endpoint] = int(by_ep.get(endpoint, 0) or 0) + 1
    service_row["updated_at"] = _now_iso()
    _save("service_metadata.json", meta)

    return {
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "results": results,
        "latency_ms": int((time.time() - t0) * 1000),
        "timestamp": _now_iso(),
    }

def example_smiles_cache_upsert(smiles, compute_svg=None, ttl_seconds=None, **_extra):
    import json, os, datetime, time, random, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0082000" if __import__("os").path.isdir("./environment_mix/0082000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "example_smiles_cache_upsert"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_used=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _check_limits():
        limits = _load("service_limits.json")
        if not isinstance(limits, dict): limits = {}
        rl = limits.get("rate_limit", {"window_seconds": 60, "max_requests": 120})
        qt = limits.get("quota", {"daily_max_requests": 20000})

        window_seconds = int(rl.get("window_seconds", 60) or 60)
        max_requests = int(rl.get("max_requests", 120) or 120)
        daily_max = int(qt.get("daily_max_requests", 20000) or 20000)

        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=window_seconds)
        day_cutoff = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str): return None
            try:
                if s.endswith("Z"): s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        in_window = 0
        in_day = 0
        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff:
                in_window += 1
            if ts >= day_cutoff:
                in_day += 1

        if in_window >= max_requests:
            return _err("RATE_LIMIT", "Too many requests in a short time window.", window_seconds=window_seconds, max_requests=max_requests)
        if in_day >= daily_max:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_max_requests=daily_max)
        return None

    limerr = _check_limits()
    if limerr:
        _log("RATE_LIMIT" if limerr["error"]["code"] == "RATE_LIMIT" else "QUOTA_EXCEEDED", detail=limerr["error"])
        return limerr

    if compute_svg is None:
        compute_svg = False
    if ttl_seconds is None:
        ttl_seconds = 604800

    if not isinstance(smiles, str) or not smiles.strip():
        _log("VALIDATION_ERROR", detail={"field": "smiles"})
        return _err("VALIDATION_ERROR", "smiles must be a non-empty string.", field="smiles")
    if not isinstance(compute_svg, bool):
        _log("VALIDATION_ERROR", detail={"field": "compute_svg"})
        return _err("VALIDATION_ERROR", "compute_svg must be a boolean.", field="compute_svg")
    if not isinstance(ttl_seconds, int) or ttl_seconds < 60 or ttl_seconds > 2592000:
        _log("VALIDATION_ERROR", detail={"field": "ttl_seconds"})
        return _err("VALIDATION_ERROR", "ttl_seconds must be an integer between 60 and 2592000.", field="ttl_seconds")

    # Ambient auth: public unless service down
    meta = _load("service_metadata.json")
    if not isinstance(meta, list): meta = []
    svc = None
    for r in meta:
        if isinstance(r, dict) and r.get("kind") == "SERVICE_STATUS" and r.get("status") == "active":
            svc = r
            break
    if svc and svc.get("service_status") == "down":
        _log("UNAUTHORIZED", detail={"reason": "service_down"})
        return _err("UNAUTHORIZED", "Access is not permitted at this time.")

    s_in = smiles.strip()

    # Very lightweight validation (offline): reject control chars; must contain at least one atom-like character
    for ch in s_in:
        o = ord(ch)
        if o < 32 and ch not in ("\t", "\n", "\r"):
            _log("VALIDATION_ERROR", detail={"reason": "control_char"})
            return _err("VALIDATION_ERROR", "Invalid SMILES: contains control characters.", field="smiles")
    atomish = any(c.isalpha() for c in s_in)
    if not atomish:
        _log("VALIDATION_ERROR", detail={"reason": "no_atoms"})
        return _err("VALIDATION_ERROR", "Invalid SMILES: does not appear to contain atoms.", field="smiles")

    # "Canonicalization" placeholder: normalize whitespace and make a stable key by hashing,
    # but keep a readable canonical_smiles as trimmed input.
    canonical_smiles = " ".join(s_in.split())
    # standardized_smiles placeholder: same as canonical for offline store
    standardized_smiles = canonical_smiles

    # Deterministic pseudo InChI and InChIKey (offline)
    h = hashlib.sha256(canonical_smiles.encode("utf-8")).hexdigest()
    inchi = f"InChI=1S/{h[:32]}"
    inchi_key = f"{h[:14].upper()}-{h[14:24].upper()}-{h[24].upper()}"
    # Ensure 27 chars (typical) by formatting: 14 + 1 + 10 + 1 + 1 = 27
    # If somehow not, pad/truncate safely.
    if len(inchi_key) != 27:
        inchi_key = (inchi_key + "X" * 27)[:27]

    payload = {
        "canonical_smiles": canonical_smiles,
        "standardized_smiles": standardized_smiles,
        "inchi": inchi,
        "inchi_key": inchi_key
    }

    if compute_svg:
        color = f"#{h[0:2]}{h[2:4]}{h[4:6]}"
        label = canonical_smiles if len(canonical_smiles) <= 64 else canonical_smiles[:61] + "..."
        svg = (
            f"<svg xmlns='http://www.w3.org/2000/svg' width='420' height='120'>"
            f"<rect x='0' y='0' width='420' height='120' fill='{color}' opacity='0.10'/>"
            f"<rect x='10' y='10' width='400' height='100' fill='white' stroke='{color}'/>"
            f"<text x='20' y='55' font-family='monospace' font-size='12' fill='black'>SMILES:</text>"
            f"<text x='20' y='75' font-family='monospace' font-size='10' fill='black'>{label}</text>"
            f"</svg>"
        )
        payload["svg_2d"] = svg

    # Upsert into service_metadata kind=SMILES_CACHE with cache_key=canonical_smiles
    nowiso = _now_iso()
    expires_at = (datetime.datetime.utcnow() + datetime.timedelta(seconds=int(ttl_seconds))).replace(microsecond=0).isoformat() + "Z"

    existing = None
    for r in meta:
        if isinstance(r, dict) and r.get("kind") == "SMILES_CACHE" and r.get("cache_key") == canonical_smiles:
            existing = r
            break

    if existing:
        if not isinstance(existing.get("cache_payload"), dict):
            existing["cache_payload"] = {}
        # merge
        for k, v in payload.items():
            existing["cache_payload"][k] = v
        existing["expires_at"] = expires_at
        existing["status"] = "active"
        existing["updated_at"] = nowiso
    else:
        meta.append({
            "id": f"md_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "kind": "SMILES_CACHE",
            "chembl_version": None,
            "release_date": None,
            "service_name": None,
            "service_status": None,
            "message": None,
            "cache_key": canonical_smiles,
            "cache_payload": dict(payload),
            "expires_at": expires_at,
            "status": "active",
            "created_at": nowiso,
            "updated_at": nowiso
        })

    _save("service_metadata.json", meta)

    resp = {
        "cache_key": canonical_smiles,
        "expires_at": expires_at,
        "payload": payload
    }
    _log("OK", detail={"cache_key": canonical_smiles, "compute_svg": compute_svg})
    return resp
